window.CGDD_DATA = {"flow":"%% Orienteering_and_Survival script flow\n%% Generated by CGDD/Export Trace Docs. Do not edit by hand.\nflowchart TD\n  ForestGameManager(\"<b>ForestGameManager</b><br/>Manages the opening cutscene, survival tutorial, firewood, campaign levels, coyote encounters, and culture-board world.\")\n  Movement(\"<b>Movement</b><br/>Provides tuned first-person walking, sprinting, jumping, and camera look.\")\n\n  ForestGameManager --> Movement\n  Movement --> ForestGameManager\n\n  classDef manager fill:#f0a202,stroke:#1a140e,color:#1a140e,stroke-width:2.5px\n  classDef actor fill:#fff8ea,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef world fill:#9cba6a,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef ui fill:#efe6cf,stroke:#c4841a,color:#1a140e,stroke-width:2px\n  classDef other fill:#efe6cf,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  class ForestGameManager manager\n  class Movement other\n","tunables":"# Tunables\n\nGenerated from `@tune` headers by the menu `CGDD/Export Trace Docs`. Hand edits are overwritten on the next export.\n\n| Script | Field | Type | Range | Default | Note |\n| --- | --- | --- | --- | --- | --- |\n| ForestGameManager | levelOneAdditionalWood | int | 1-100 | 14 | Extra firewood required in Level 1. |\n| ForestGameManager | levelOneMatchPickupCount | int | 0-20 | 4 | Random match bundles spawned in Level 1. |\n| ForestGameManager | levelTwoMatchSpawnMinDelay | float | 5-300 | 18 | Minimum delay between new match pickups in Level 2. |\n| ForestGameManager | levelTwoMatchSpawnMaxDelay | float | 5-600 | 28 | Maximum delay between new match pickups in Level 2. |\n| ForestGameManager | levelThreeMatchSpawnMinDelay | float | 5-300 | 30 | Minimum delay between new match pickups in Level 3. |\n| ForestGameManager | levelThreeMatchSpawnMaxDelay | float | 5-600 | 48 | Maximum delay between new match pickups in Level 3. |\n| ForestGameManager | maxCampaignMatchPickups | int | 1-10 | 3 | Maximum uncollected campaign match bundles at once. |\n| ForestGameManager | campaignMatchSpawnMinDistance | float | 4-100 | 8 | Minimum distance from player for a new campaign match bundle. |\n| ForestGameManager | campaignMatchSpawnMaxDistance | float | 5-200 | 24 | Maximum distance from player for a new campaign match bundle. |\n| ForestGameManager | levelOneNoteCount | int | 0-20 | 5 | Random readable notes placed in Level 1. |\n| ForestGameManager | coyoteSpawnMinDelay | float | 1-300 | 32 | Minimum random delay before a Level 1 coyote spawns. |\n| ForestGameManager | coyoteSpawnMaxDelay | float | 1-600 | 52 | Maximum random delay before a Level 1 coyote spawns. |\n| ForestGameManager | coyoteRespawnDelay | float | 0-600 | 20 | Extra cooldown after each encounter before another coyote can spawn. |\n| ForestGameManager | chasingFlashesToScareCoyote | int | 1-10 | 4 | Flashlight flashes needed to scare a coyote during its chase. |\n| ForestGameManager | coyotesToKillForJacket | int | 1-100 | 10 | Coyote kills needed to unlock the gun progression and jacket. |\n| ForestGameManager | levelTwoCoyoteMinDelay | float | 1-300 | 5 | Minimum Level 2 coyote spawn delay. |\n| ForestGameManager | levelTwoCoyoteMaxDelay | float | 1-600 | 8 | Maximum Level 2 coyote spawn delay. |\n| ForestGameManager | levelTwoCoyoteCooldown | float | 0-300 | 1 | Extra Level 2 cooldown after each coyote encounter. |\n| ForestGameManager | levelTwoCoyoteWarningSeconds | float | 1-20 | 4.5 | Warning time before a Level 2 Coyote starts chasing. |\n| ForestGameManager | gunShotRange | float | 1-300 | 80 | Maximum distance for shooting a Coyote. |\n| ForestGameManager | gunShotCooldown | float | 0.05-5 | — | Minimum time between gunshots. |\n| ForestGameManager | levelThreeDeadlineSeconds | float | 30-1800 | 420 | Maximum exploration time before Level 4. |\n| ForestGameManager | levelThreeCoyoteDelayMultiplier | float | 1-10 | 4 | Multiplier for coyote delay during Level 3. |\n| ForestGameManager | levelThreeNoteTexts | string[] | 1-20 | — | Editable campaign note text used to reveal the island story. |\n| ForestGameManager | jacketColdDrainMultiplier | float | 0-1 | — | Hypothermia drain multiplier while wearing the jacket. |\n| ForestGameManager | godHeightInPlayerHeights | float | 2-50 | 22 | Boss height as a multiple of player height. |\n| ForestGameManager | cultureCampMapPosition | Vector2 | 0-1 | — | Normalized terrain position of the abandoned campsite. |\n| ForestGameManager | cultureTempleMapPosition | Vector2 | 0-1 | — | Normalized terrain position of the western temple. |\n| ForestGameManager | cultureEyeGroveMapPosition | Vector2 | 0-1 | — | Normalized terrain position of the eye-tree grove. |\n| ForestGameManager | cultureShelterMapPosition | Vector2 | 0-1 | — | Normalized terrain position of the abandoned shelter. |\n| ForestGameManager | godChaseSpeed | float | 1-20 | 3.4 | God movement speed during the final chase. |\n| ForestGameManager | godStartDistance | float | 10-200 | 55 | Distance behind the player when the chase begins. |\n| ForestGameManager | godExitInset | float | 5-100 | 14 | How far inside the terrain edge the final capture beacon appears. |\n| ForestGameManager | godGrabDistance | float | 1-50 | 5 | Distance at which the God catches the player during the chase. |\n| ForestGameManager | godFinalFadeSeconds | float | 0.1-10 | 2.5 | Duration of the final screen fade before the ending. |\n| ForestGameManager | godChantVolume | float | 0-1 | — | Volume of the looping chant during the God chase. |\n| ForestGameManager | godCatchGraceSeconds | float | 0-180 | 60 | Seconds the God chases before it is allowed to catch the player. |\n| ForestGameManager | godGrowthPlayerHeightsPerSecond | float | 0-2 | — | How many player-heights the God grows each second. |\n| ForestGameManager | godMaxHeightInPlayerHeights | float | 2-100 | 38 | Maximum God height as a multiple of player height. |\n| ForestGameManager | gunBodyHitRadius | float | 0.1-5 | — | Shot tolerance around the Coyote body. |\n| ForestGameManager | levelFourPlayerSpeed | float | 0-100 | 30 | Player movement speed during the Level 4 chase. |\n| ForestGameManager | levelFourCoyoteMinDelay | float | 5-300 | 14 | Minimum Level 4 Coyote delay. |\n| ForestGameManager | levelFourCoyoteMaxDelay | float | 5-600 | 22 | Maximum Level 4 Coyote delay. |\n| ForestGameManager | levelFourCoyoteCooldown | float | 0-300 | 2 | Cooldown after a Level 4 Coyote encounter. |\n| ForestGameManager | levelFourCoyoteWarningSeconds | float | 1-20 | 3 | Warning time before a Level 4 Coyote chases. |\n| ForestGameManager | levelFourCoyoteSpawnMinDistance | float | 3-100 | 8 | Minimum distance ahead for a Level 4 Coyote spawn. |\n| ForestGameManager | levelFourCoyoteSpawnMaxDistance | float | 4-150 | 16 | Maximum distance ahead for a Level 4 Coyote spawn. |\n| ForestGameManager | levelFourCoyoteLateralRange | float | 0-30 | 2 | Side-to-side spawn spread for Level 4 Coyotes. |\n| Movement | moveSpeed | float | 0-20 | 4 | Base walking speed for exploration. |\n| Movement | jumpHeight | float | 0-5 | 0.75 | Player jump height. |\n| Movement | sprintMultiplier | float | 1-3 | 1.6 | Speed multiplier while holding Shift. |\n\n","challenge":"# How the challenge changes\n\nLook first at whether win and loss change, then at whether the player's verb changes. If neither changes, it is the same game, just tighter or looser.\n\n| Change | Win/loss changed | Verb changed | Data | Script.field |\n| --- | --- | --- | --- | --- |\n| Start: (describe baseline feel) | — (baseline) | — (player verb) | field=default | ScriptName.field |\n| Coyote defense and death checkpoint | No (coyote catch / hypothermia still cause death; Level 1 completion still wins) | No (flash the flashlight) | coyoteSpawnMinDelay=32, coyoteSpawnMaxDelay=52, coyoteRespawnDelay=20, chasingFlashesToScareCoyote=4 | ForestGameManager fields |\n| Campaign expansion: gun, jacket, notes, map, and God chase | Yes: reaching the map edge starts the only ending, where the God catches the player; being caught earlier also ends the run | Yes: explore and collect notes, shoot coyotes, then run from the God | coyotesToKillForJacket=10, levelThreeDeadlineSeconds=420, levelThreeCoyoteDelayMultiplier=4, jacketColdDrainMultiplier=0.12, godHeightInPlayerHeights=15, godChaseSpeed=6.1, godExitInset=14 | ForestGameManager fields |\n\nThe final sequence has one ending: the player cannot defeat the God or escape the island. Reaching the far map edge completes the chase by triggering the God’s scripted capture; the God can also catch the player before they reach it. Level 3 advances to Level 4 when all three campaign notes are read or the seven-minute timer expires.\n","devlog":"# DEVLOG\n\nOnly append. Do not edit old sections. Two samples stay so students can see the format.\n\nOnly changes to the game itself are logged: the verb, win and loss, pressure, and what the player can feel.\nSite language, diagram styling, and click-to-read-script do not go into an Interaction or a Stage Reflection.\n\nEach gameplay change should add a section `## Interaction NNN — title` (the Agent can append this when it changes the game).\nAdd `## Stage Reflection NNN — title` only when you ask for one: Keep / Change / Cut, and which AI suggestions you accepted or rejected. That reflection stays on the game.\n\n## Interaction 000 — EXAMPLE (sample, do not delete)\n\n- Date: —\n- Who asked: teacher (sample)\n- Request: Tighten one tunable and see if it is still the same game.\n- What changed: Sample only. The current code was not changed. A real change would touch only one `@tune` field.\n- Result: The player's verb did not change. Win and loss did not change. Pressure changed, not the skeleton.\n\n## Stage Reflection 000 — EXAMPLE (sample, do not delete)\n\n### Keep\n- A core verb you can say in one sentence, and a clear win/loss.\n\n### Change\n- To make it harder, turn an existing `@tune` first. Do not add a new system yet.\n\n### Cut\n- No shop, no deep inventory, no optimization that is off-lesson.\n\n### AI\n- Accept: tune feel with existing fields; avoid opening new scripts.\n- Reject: GraphView, object pools, long hand-written scene YAML. This class is about script relationships and tunable numbers.\n\n\n## Interaction 001 — Match pickups and field notes\n\n- Date: 2026-10-26\n- Who asked: student\n- Request: Add scarce match pickups and readable notes with distinct visuals.\n- What changed: Level 1 now places four match bundles among fourteen firewood pickups; each bundle adds two matches. Five readable notes spawn at separate random locations and open/close with R. Match count, spawn counts, spacing, and note text can be edited in the ForestGameManager Inspector.\n- Result: The player can search for extra warmth and read environmental story details. Win/loss and the core survival objective did not change.\n\n\n## Interaction 002 — Coyote chase defense and helicopter checkpoint\n\n- Date: 2026-10-27\n- Who asked: student\n- Request: Let the player scare coyotes during a chase, make spawn timing editable, and keep deposited firewood after death.\n- What changed: Flashing can now repel a chasing coyote after four aimed flashes. Spawn frequency is tunable with a random minimum/maximum delay plus a fixed post-encounter cooldown. Death restarts preserve firewood already deposited at the helicopter; carried wood is lost. Level replay after completion still begins from the tutorial deposit.\n- Result: Win/loss conditions and the player’s flashlight action stayed the same. The coyote chase is more recoverable and helicopter deposits now preserve objective progress.\n\n\n## Interaction 003 — Campaign expansion and God capture ending\n\n- Date: 2026-10-30\n- Who asked: student\n- Request: Add the culture-board ideas as playable spaces and story clues, then add Levels 2–4 with the requested controls and final chase.\n- What changed: Level 2 teaches the separate flashlight and gun actions: flashlight misses repel coyotes, while a body hit kills one; ten kills unlock the jacket and Level 3. The jacket reduces cold drain to 12%. Level 3 places three campaign notes and a map opened with F; finding every note or reaching seven minutes starts Level 4. The final God is a bipedal, Inspector-scaled stand-in that chases the player to the far map edge. Reaching the edge triggers the only ending, a scripted capture; the God can also catch the player earlier. Added abandoned camp, shelter, temple, eye-tree grove, and repeated trail symbols as in-world culture-board landmarks.\n- Result: The player now explores, reads, aims and shoots, and runs. The final outcome is still capture, with the edge serving as the chase objective that triggers it. Level progression adds new actions and pressure rather than a separate safe victory.\n\n## Interaction 004 — Gun hunt and growing God chase\n\n- Date: 2026-10-30\n- Who asked: student\n- Request: Make the gun mode more active, support warmth in Levels 2–3, make Level 3 easier to navigate, and give the final chase more time and escalation.\n- What changed: Gunfire now plays the project’s gun sound and sends a visible projectile; direct body hits kill Coyotes while misses scare them away. Level 2 uses shorter Coyote spawn intervals, and Levels 2–3 receive timed match bundles. Level 3 points to the F map, nearby notes, and named landmarks. In Level 4 the God chases immediately, grows over time, moves more slowly, and cannot catch the player for 60 seconds; the chant loops during the chase.\n- Result: Shooting, survival supply, note finding, and escape pressure are more active. The player’s actions and campaign ending remain the same: reaching the God ends in capture.\n\n\n## Interaction 005 — Cutscene death recovery and level skip\n\n- Date: 2026-10-30\n- Who asked: student\n- Request: Fix repeated death after the Level 1-to-2 Coyote transition and add a key to skip a level.\n- What changed: Dying to the Level 2 tutorial Coyote now offers a safe continuation into Level 2 instead of replaying that Coyote encounter. The restart button and R key use the same recovery route. Pressing P skips the active tutorial or campaign level and advances to the next stage; during the final chase it triggers the existing capture ending.\n- Result: The transition cannot trap the player in a repeated Coyote death, and P advances the campaign without changing its final outcome.\n\n\n## Interaction 006 — Accessible notes and a dangerous final run\n\n- Date: 2026-10-30\n- Who asked: student\n- Request: Move the blocked Level 3 note, make the God chase feel faster, add Coyotes to Level 4, and change the map-edge ending.\n- What changed: Level 3 notes now search nearby ground for a player-sized clear spot around each landmark. Level 4 sets movement speed to 30, places a Coyote in the route at the start, and spawns later Coyotes on an adjustable timer. Reaching the beacon triggers the God’s three-line confrontation before the capture animation. The existing jumpscare scream plays when the God bites.\n- Result: Note spots avoid scene colliders, the final run adds immediate enemy pressure, and reaching the map edge leads to a distinct capture scene. The final outcome remains capture.\n","scripts":{"ForestGameManager":{"path":"Assets/Script/ForestGameManager.cs","role":"Manages the opening cutscene, survival tutorial, firewood, campaign levels, coyote encounters, and culture-board world.","source":"using UnityEngine;\nusing UnityEngine.UI;\nusing UnityEngine.EventSystems;\nusing System.Collections;\nusing System.Collections.Generic;\n\n// @role Manages the opening cutscene, survival tutorial, firewood, campaign levels, coyote encounters, and culture-board world.\n// @calls Movement\n// @tune levelOneAdditionalWood:int:1-100:Extra firewood required in Level 1.\n// @tune levelOneMatchPickupCount:int:0-20:Random match bundles spawned in Level 1.\n// @tune levelTwoMatchSpawnMinDelay:float:5-300:Minimum delay between new match pickups in Level 2.\n// @tune levelTwoMatchSpawnMaxDelay:float:5-600:Maximum delay between new match pickups in Level 2.\n// @tune levelThreeMatchSpawnMinDelay:float:5-300:Minimum delay between new match pickups in Level 3.\n// @tune levelThreeMatchSpawnMaxDelay:float:5-600:Maximum delay between new match pickups in Level 3.\n// @tune maxCampaignMatchPickups:int:1-10:Maximum uncollected campaign match bundles at once.\n// @tune campaignMatchSpawnMinDistance:float:4-100:Minimum distance from player for a new campaign match bundle.\n// @tune campaignMatchSpawnMaxDistance:float:5-200:Maximum distance from player for a new campaign match bundle.\n// @tune levelOneNoteCount:int:0-20:Random readable notes placed in Level 1.\n// @tune coyoteSpawnMinDelay:float:1-300:Minimum random delay before a Level 1 coyote spawns.\n// @tune coyoteSpawnMaxDelay:float:1-600:Maximum random delay before a Level 1 coyote spawns.\n// @tune coyoteRespawnDelay:float:0-600:Extra cooldown after each encounter before another coyote can spawn.\n// @tune chasingFlashesToScareCoyote:int:1-10:Flashlight flashes needed to scare a coyote during its chase.\n// @tune coyotesToKillForJacket:int:1-100:Coyote kills needed to unlock the gun progression and jacket.\n// @tune levelTwoCoyoteMinDelay:float:1-300:Minimum Level 2 coyote spawn delay.\n// @tune levelTwoCoyoteMaxDelay:float:1-600:Maximum Level 2 coyote spawn delay.\n// @tune levelTwoCoyoteCooldown:float:0-300:Extra Level 2 cooldown after each coyote encounter.\n// @tune levelTwoCoyoteWarningSeconds:float:1-20:Warning time before a Level 2 Coyote starts chasing.\n// @tune gunShotRange:float:1-300:Maximum distance for shooting a Coyote.\n// @tune gunShotCooldown:float:0.05-5:Minimum time between gunshots.\n// @tune levelThreeDeadlineSeconds:float:30-1800:Maximum exploration time before Level 4.\n// @tune levelThreeCoyoteDelayMultiplier:float:1-10:Multiplier for coyote delay during Level 3.\n// @tune levelThreeNoteTexts:string[]:1-20:Editable campaign note text used to reveal the island story.\n// @tune jacketColdDrainMultiplier:float:0-1:Hypothermia drain multiplier while wearing the jacket.\n// @tune godHeightInPlayerHeights:float:2-50:Boss height as a multiple of player height.\n// @tune cultureCampMapPosition:Vector2:0-1:Normalized terrain position of the abandoned campsite.\n// @tune cultureTempleMapPosition:Vector2:0-1:Normalized terrain position of the western temple.\n// @tune cultureEyeGroveMapPosition:Vector2:0-1:Normalized terrain position of the eye-tree grove.\n// @tune cultureShelterMapPosition:Vector2:0-1:Normalized terrain position of the abandoned shelter.\n// @tune godChaseSpeed:float:1-20:God movement speed during the final chase.\n// @tune godStartDistance:float:10-200:Distance behind the player when the chase begins.\n// @tune godExitInset:float:5-100:How far inside the terrain edge the final capture beacon appears.\n// @tune godGrabDistance:float:1-50:Distance at which the God catches the player during the chase.\n// @tune godFinalFadeSeconds:float:0.1-10:Duration of the final screen fade before the ending.\n// @tune godChantVolume:float:0-1:Volume of the looping chant during the God chase.\n// @tune godCatchGraceSeconds:float:0-180:Seconds the God chases before it is allowed to catch the player.\n// @tune godGrowthPlayerHeightsPerSecond:float:0-2:How many player-heights the God grows each second.\n// @tune godMaxHeightInPlayerHeights:float:2-100:Maximum God height as a multiple of player height.\n// @tune gunBodyHitRadius:float:0.1-5:Shot tolerance around the Coyote body.\n// @tune levelFourPlayerSpeed:float:0-100:Player movement speed during the Level 4 chase.\n// @tune levelFourCoyoteMinDelay:float:5-300:Minimum Level 4 Coyote delay.\n// @tune levelFourCoyoteMaxDelay:float:5-600:Maximum Level 4 Coyote delay.\n// @tune levelFourCoyoteCooldown:float:0-300:Cooldown after a Level 4 Coyote encounter.\n// @tune levelFourCoyoteWarningSeconds:float:1-20:Warning time before a Level 4 Coyote chases.\n// @tune levelFourCoyoteSpawnMinDistance:float:3-100:Minimum distance ahead for a Level 4 Coyote spawn.\n// @tune levelFourCoyoteSpawnMaxDistance:float:4-150:Maximum distance ahead for a Level 4 Coyote spawn.\n// @tune levelFourCoyoteLateralRange:float:0-30:Side-to-side spawn spread for Level 4 Coyotes.\n\n/// <summary>Opening cutscene, Tutorial 2, and Level 1 survival flow.</summary>\npublic partial class ForestGameManager : MonoBehaviour\n{\n    public static bool IsPlaying { get; private set; }\n\n    [Header(\"Firewood\")]\n    [Min(1)] public int levelOneAdditionalWood = 14;\n    [Min(1f)] public float woodPickupDistance = 2.2f;\n    [Min(1f)] public float helicopterDepositDistance = 6f;\n    [Min(1f)] public float woodSpawnMinRadius = 30f;\n    [Min(1f)] public float woodSpawnMaxRadius = 105f;\n    [Min(0f)] public float woodMinimumSeparation = 22f;\n    [Min(1f)] public float woodChimeDistance = 7f;\n    [Tooltip(\"If Level 1 passes this long without a pickup, place one rescue stick nearby.\")]\n    [Min(1f)] public float woodRescueSpawnDelay = 20f;\n    [Tooltip(\"Minimum distance from the player for a rescue stick.\")]\n    [Min(1f)] public float woodRescueSpawnMinDistance = 10f;\n    [Tooltip(\"Maximum distance from the player for a rescue stick.\")]\n    [Min(1f)] public float woodRescueSpawnMaxDistance = 18f;\n    [Tooltip(\"Warm marker light attached to each firewood pickup.\")]\n    [Min(0f)] public float woodMarkerLightIntensity = 1.6f;\n    [Min(1f)] public float woodMarkerLightRange = 5f;\n    public AudioClip woodPickupChime;\n\n    [Header(\"Match Pickups\")]\n    [Tooltip(\"Match bundles spawned across Level 1; each bundle adds this many matches.\")]\n    [Min(0)] public int levelOneMatchPickupCount = 4;\n    [Min(1)] public int matchesPerPickup = 2;\n    [Min(1f)] public float matchPickupDistance = 2.2f;\n    [Min(0f)] public float matchMinimumSeparation = 16f;\n    [Min(0f)] public float matchMarkerLightIntensity = 1.1f;\n    [Min(1f)] public float matchMarkerLightRange = 4f;\n    [Header(\"Campaign Match Supplies\")]\n    [Min(1f)] public float levelTwoMatchSpawnMinDelay = 18f;\n    [Min(1f)] public float levelTwoMatchSpawnMaxDelay = 28f;\n    [Min(1f)] public float levelThreeMatchSpawnMinDelay = 30f;\n    [Min(1f)] public float levelThreeMatchSpawnMaxDelay = 48f;\n    [Min(1)] public int maxCampaignMatchPickups = 3;\n    [Min(4f)] public float campaignMatchSpawnMinDistance = 8f;\n    [Min(5f)] public float campaignMatchSpawnMaxDistance = 24f;\n\n    [Header(\"World Notes\")]\n    [Tooltip(\"Edit these strings to change notes or add new note entries.\")]\n    [TextArea(3, 7)] public List<string> worldNotes = new List<string>\n    {\n        \"I don’t know where this place is.\\nI can see Earth from up here, but wasn’t I just on Earth?\\nI’m in space, but for some reason I can breathe…\\nIt must be a dream.\",\n        \"There is something strange about the Coyotes here.\\nThey seem strangely aggressive, but also quite smart.\\nI once saw them talking to each other.\\nI know that sounds strange, but they were speaking in a language I didn’t recognize…\\nIt didn’t sound like any language I knew.\",\n        \"Who is ####?\\nI keep hearing that name mentioned.\",\n        \"You should really see the strange temples to the west.\\nThey’re really quite bizarre.\\nAlso, I think the trees have eyes.\",\n        \"It’s really cold here…\\nI guess that’s to be expected when you’re in space.\\nOne minute I was in bed, and now I’m here.\\nIt was as if I’d been spirited away.\"\n    };\n    [Min(0)] public int levelOneNoteCount = 5;\n    [Min(1f)] public float noteReadDistance = 2.5f;\n\n    [Header(\"Sound Effects\")]\n    public AudioClip flashlightToggleSound;\n    public AudioClip hypothermiaBreathingSound;\n    public AudioClip coyoteJumpscareSound;\n    public AudioClip coyoteWarningSound;\n    [Range(0f, 1f)] public float coyoteWarningVolume = .16f;\n    [Range(0f, 1f)] public float jumpscareVolume = 1f;\n\n    [Header(\"Flashlight\")]\n    [Min(1f)] public float flashlightRange = 14f;\n    [Min(0f)] public float flashlightIntensity = 2.2f;\n    [Range(1f, 89f)] public float coyoteFlashAngle = 55f;\n    [Min(1)] public int flashesToScareCoyote = 10;\n\n    [Header(\"Coyote Encounter\")]\n    [Tooltip(\"Optional replacement model. Leave empty to use the generated stand-in.\")]\n    public GameObject coyotePrefab;\n    [Min(1f)] public float tutorialCoyoteDistance = 13f;\n    [Tooltip(\"Random base delay between Level 1 coyote encounters. The first encounter also uses this range.\")]\n    [Min(1f)] public float coyoteSpawnMinDelay = 32f;\n    [Tooltip(\"Maximum random base delay between Level 1 coyote encounters.\")]\n    [Min(1f)] public float coyoteSpawnMaxDelay = 52f;\n    [Tooltip(\"Additional fixed cooldown after a coyote is scared away. Increase this to make encounters less frequent.\")]\n    [Min(0f)] public float coyoteRespawnDelay = 20f;\n    [Tooltip(\"Successful flashlight flashes needed after the coyote starts chasing. Warning-stage flashes use flashesToScareCoyote.\")]\n    [Min(1)] public int chasingFlashesToScareCoyote = 4;\n    [Min(1f)] public float coyoteWarningSeconds = 4f;\n    [Min(0.1f)] public float coyoteChaseSpeed = 5.5f;\n    [Min(0.5f)] public float coyoteCatchDistance = 1.35f;\n\n    [Header(\"Hypothermia\")]\n    [Range(1f, 100f)] public float startingHypothermia = 100f;\n    [Min(0.001f)] public float hypothermiaDrainPerSecond = 3f;\n    [Range(1f, 99f)] public float tutorialColdStart = 58f;\n    [Min(0.001f)] public float tutorialHypothermiaDrainPerSecond = 2f;\n    [Range(1f, 50f)] public float coldWarningThreshold = 25f;\n    [Min(1f)] public float helicopterWarmthRadius = 3.5f;\n    [Min(1)] public int startingMatches = 3;\n    [Min(0f)] public float matchResetAmount = 100f;\n\n    [Header(\"Crash Site & Fog\")]\n    [Min(0f)] public float crashFogDensity = 0.014f;\n    [Min(1f)] public float crashLightRange = 45f;\n    [Min(0f)] public float crashLightIntensity = 7f;\n    [Min(0f)] public float levelOneFogDensity = 0.06f;\n    [Min(0f)] public float levelOneAmbientIntensity = 0.008f;\n    [Min(0f)] public float levelOneDirectionalLightIntensity = 0.08f;\n    [Min(20f)] public float levelOneViewDistance = 48f;\n    [Tooltip(\"Range of the crashed helicopter light, visible through the fog.\")]\n    [Min(1f)] public float levelOneCrashLightRange = 32f;\n    [Min(0f)] public float levelOneCrashLightIntensity = 6f;\n    [Min(1f)] public float crashLandingClearRadius = 14f;\n\n    [Header(\"Map Boundary\")]\n    [Tooltip(\"Inset from the terrain edge for the invisible wall.\")]\n    [Min(0f)] public float mapBoundaryInset = 4f;\n    [Min(1f)] public float mapBoundaryWallThickness = 2f;\n\n    enum Phase { Title, Cutscene, TutorialWood, TutorialDeliver, TutorialFlashlight, TutorialCold, TutorialCoyote, Level1, Level2IntroCoyote, Level2, Level3, Level4, CampaignTransition, FinalEnding, GameOver, Complete }\n    sealed class WoodPickup\n    {\n        public GameObject root;\n        public bool tutorial;\n        public bool chimePlayed;\n    }\n    sealed class MatchPickup { public GameObject root; }\n    sealed class WorldNotePickup { public GameObject root; public string text; public bool campaignNote; public int campaignIndex; }\n\n    Transform player;\n    Transform playerCamera;\n    Transform helicopter;\n    Terrain terrain;\n    Movement movement;\n    Light flashlight;\n    Light directionalLight;\n    Camera gameplayCamera;\n    AudioSource audioSource;\n    AudioSource coyoteAudioSource;\n    AudioSource breathingAudioSource;\n    Light crashLight;\n    Light introHelicopterLight;\n    ParticleSystem crashFireParticles;\n\n    readonly List<WoodPickup> woodPickups = new List<WoodPickup>();\n    readonly List<MatchPickup> matchPickups = new List<MatchPickup>();\n    readonly List<WorldNotePickup> notePickups = new List<WorldNotePickup>();\n    readonly List<Transform> fireFlames = new List<Transform>();\n    readonly List<Renderer> hiddenForFlight = new List<Renderer>();\n\n    Canvas canvas;\n    Image titleBackground;\n    Image blackoutOverlay;\n    Image coldOverlay;\n    Image scareOverlay;\n    Image hypothermiaFill;\n    Text titleText;\n    Text startPrompt;\n    Text dialogueText;\n    Text objectiveText;\n    Text inventoryText;\n    Text hintText;\n    GameObject hudRoot;\n    GameObject dialoguePanel;\n    GameObject notePanel;\n    Text noteText;\n    GameObject endPanel;\n\n    Phase phase = Phase.Title;\n    bool skipCutscene;\n    bool coldWarningShown;\n    float hypothermia;\n    float coyoteTimer;\n    float levelCoyoteTimer;\n    float woodRescueTimer;\n    float campaignMatchSpawnTimer;\n    float fireLevel;\n    float lookPitch;\n    Vector3 cameraBaseLocalPosition;\n    int matches;\n    int woodCarried;\n    int woodDelivered;\n    int coyoteFlashHits;\n    Transform activeCoyote;\n    bool coyoteChasing;\n    bool coyoteEscaping;\n    bool noteOpen;\n    bool movementWasEnabledBeforeNote;\n    Phase phaseBeforeGameOver;\n    Vector3 crashCheckpoint;\n    Quaternion crashCheckpointRotation;\n    Vector3 levelOneCheckpoint;\n    Quaternion levelOneCheckpointRotation;\n    Color savedCameraBackground;\n    CameraClearFlags savedCameraClearFlags;\n\n    void Awake()\n    {\n        IsPlaying = false;\n        Time.timeScale = 1f;\n    }\n\n    void Start()\n    {\n        Time.timeScale = 1f;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        player = GameObject.FindGameObjectWithTag(\"Player\")?.transform;\n        if (player == null)\n        {\n            Debug.LogError(\"ForestGameManager needs a GameObject tagged Player.\");\n            enabled = false;\n            return;\n        }\n\n        movement = player.GetComponent<Movement>();\n        Camera playerCam = player.GetComponentInChildren<Camera>(true);\n        if (playerCam != null)\n        {\n            gameplayCamera = playerCam;\n            playerCamera = playerCam.transform;\n            savedCameraBackground = playerCam.backgroundColor;\n            savedCameraClearFlags = playerCam.clearFlags;\n        }\n        GameObject sun = GameObject.Find(\"Directional Light\");\n        if (sun != null) directionalLight = sun.GetComponent<Light>();\n        flashlight = FindFlashlight();\n        if (flashlight != null)\n        {\n            flashlight.range = flashlightRange;\n            flashlight.intensity = flashlightIntensity;\n            flashlight.enabled = false;\n        }\n\n        terrain = Terrain.activeTerrain;\n        CreateMapBoundaryWalls();\n        GameObject heli = GameObject.Find(\"Helicopter\") ?? GameObject.Find(\"OH-58D\") ?? GameObject.Find(\"Intro Helicopter\");\n        if (heli != null) helicopter = heli.transform;\n        if (helicopter == null)\n        {\n            GameObject model = Resources.Load<GameObject>(\"Models/HelicopterModel/OH-58D\");\n            if (model != null)\n            {\n                helicopter = Instantiate(model, player.position + Vector3.up * 80f + player.forward * 15f, player.rotation).transform;\n                helicopter.name = \"Intro Helicopter\";\n            }\n            else Debug.LogWarning(\"No helicopter found in the scene or Resources/Models/HelicopterModel/OH-58D.\");\n        }\n        if (helicopter != null)\n        {\n            helicopter.position = player.position + Vector3.up * 80f + player.forward * 15f;\n            CreateCrashFire(helicopter);\n            CreateCrashLight(helicopter);\n            CreateIntroHelicopterLight(helicopter);\n        }\n\n        audioSource = GetComponent<AudioSource>();\n        if (audioSource == null) audioSource = gameObject.AddComponent<AudioSource>();\n        audioSource.playOnAwake = false;\n        audioSource.loop = false;\n        audioSource.volume = 1f;\n        audioSource.ignoreListenerVolume = true;\n        audioSource.Stop();\n        audioSource.spatialBlend = 0f;\n        coyoteAudioSource = gameObject.AddComponent<AudioSource>();\n        coyoteAudioSource.playOnAwake = false;\n        coyoteAudioSource.spatialBlend = 0f;\n        coyoteAudioSource.loop = true;\n        coyoteAudioSource.clip = coyoteWarningSound;\n        coyoteAudioSource.volume = coyoteWarningVolume;\n        breathingAudioSource = gameObject.AddComponent<AudioSource>();\n        breathingAudioSource.playOnAwake = false;\n        breathingAudioSource.spatialBlend = 0f;\n        breathingAudioSource.loop = true;\n        breathingAudioSource.clip = hypothermiaBreathingSound;\n        breathingAudioSource.volume = .65f;\n\n        CacheCultureLighting();\n        BuildUI();\n        BuildCampaignUI();\n        CreateCultureBoardWorld();\n        RenderSettings.fog = false;\n        if (playerCamera != null)\n        {\n            playerCamera.SetParent(null, true);\n            Camera cam = playerCamera.GetComponent<Camera>();\n            if (cam != null)\n            {\n                cam.clearFlags = CameraClearFlags.SolidColor;\n                cam.backgroundColor = new Color(.006f, .01f, .025f);\n            }\n            Vector3 cameraStart = helicopter != null ? helicopter.position - helicopter.forward * 10f + Vector3.up * 4f : player.position + Vector3.up * 90f;\n            playerCamera.position = cameraStart;\n            if (helicopter != null) playerCamera.rotation = Quaternion.LookRotation(helicopter.position - cameraStart);\n        }\n\n        HideFlightForeground(player.position, 50f);\n        matches = startingMatches;\n        hypothermia = startingHypothermia;\n        UpdateHud();\n    }\n\n    Light FindFlashlight()\n    {\n        Transform named = player.Find(\"Main Camera/Flashlight\") ?? player.Find(\"Flashlight\");\n        Light namedLight = named != null ? named.GetComponent<Light>() : null;\n        if (namedLight != null) return namedLight;\n        foreach (Light candidate in player.GetComponentsInChildren<Light>(true))\n            if (candidate.gameObject.name.IndexOf(\"flash\", System.StringComparison.OrdinalIgnoreCase) >= 0 || candidate.type == LightType.Spot)\n                return candidate;\n        return null;\n    }\n\n    void BuildUI()\n    {\n        GameObject canvasObject = new GameObject(\"Survival UI\");\n        canvas = canvasObject.AddComponent<Canvas>();\n        canvas.renderMode = RenderMode.ScreenSpaceOverlay;\n        canvas.sortingOrder = 100;\n        CanvasScaler scaler = canvasObject.AddComponent<CanvasScaler>();\n        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\n        scaler.referenceResolution = new Vector2(1920, 1080);\n        scaler.matchWidthOrHeight = .5f;\n        canvasObject.AddComponent<GraphicRaycaster>();\n\n        titleBackground = NewImage(canvas.transform, \"Title Background\", Vector2.zero, Vector2.one);\n        titleBackground.color = new Color(.012f, .022f, .04f, 1f);\n        coldOverlay = NewImage(canvas.transform, \"Cold Screen Tint\", Vector2.zero, Vector2.one);\n        coldOverlay.color = new Color(.06f, .28f, .95f, 0f);\n        scareOverlay = NewImage(canvas.transform, \"Coyote Jumpscare Tint\", Vector2.zero, Vector2.one);\n        scareOverlay.color = new Color(.75f, .015f, .025f, 0f);\n        blackoutOverlay = NewImage(canvas.transform, \"Blackout\", Vector2.zero, Vector2.one);\n        blackoutOverlay.color = Color.black;\n        blackoutOverlay.gameObject.SetActive(false);\n\n        titleText = NewText(canvas.transform, \"Title\", \"ORIENTEERING\\n& SURVIVAL\", 52, new Vector2(.15f, .58f), new Vector2(.85f, .78f));\n        titleText.fontStyle = FontStyle.Bold;\n        titleText.alignment = TextAnchor.MiddleCenter;\n        startPrompt = NewText(canvas.transform, \"Start Prompt\", \"PRESS ANY BUTTON TO BEGIN\", 24, new Vector2(.15f, .12f), new Vector2(.85f, .22f));\n        startPrompt.alignment = TextAnchor.MiddleCenter;\n\n        hudRoot = new GameObject(\"Gameplay HUD\", typeof(RectTransform));\n        hudRoot.transform.SetParent(canvas.transform, false);\n        RectTransform hudRect = (RectTransform)hudRoot.transform;\n        hudRect.anchorMin = Vector2.zero;\n        hudRect.anchorMax = Vector2.one;\n        hudRect.offsetMin = Vector2.zero;\n        hudRect.offsetMax = Vector2.zero;\n        objectiveText = NewText(hudRoot.transform, \"Objective\", \"\", 25, new Vector2(.035f, .89f), new Vector2(.48f, .97f));\n        objectiveText.alignment = TextAnchor.UpperLeft;\n        inventoryText = NewText(hudRoot.transform, \"Inventory\", \"\", 21, new Vector2(.035f, .82f), new Vector2(.52f, .89f));\n        inventoryText.alignment = TextAnchor.UpperLeft;\n        Text coldLabel = NewText(hudRoot.transform, \"Hypothermia Label\", \"BODY WARMTH\", 20, new Vector2(.78f, .93f), new Vector2(.97f, .97f));\n        coldLabel.alignment = TextAnchor.MiddleRight;\n        Image coldBack = NewImage(hudRoot.transform, \"Hypothermia Bar Background\", new Vector2(.79f, .895f), new Vector2(.97f, .925f));\n        coldBack.color = new Color(.04f, .08f, .16f, .9f);\n        hypothermiaFill = NewImage(hudRoot.transform, \"Hypothermia Bar\", new Vector2(.795f, .9f), new Vector2(.965f, .92f));\n        // Filled UI Images need a sprite; a null sprite can render as a full quad and ignore fillAmount.\n        hypothermiaFill.sprite = Sprite.Create(Texture2D.whiteTexture, new Rect(0f, 0f, 1f, 1f), new Vector2(.5f, .5f));\n        hypothermiaFill.type = Image.Type.Filled;\n        hypothermiaFill.fillMethod = Image.FillMethod.Horizontal;\n        hypothermiaFill.fillOrigin = (int)Image.OriginHorizontal.Left;\n        hypothermiaFill.color = new Color(.15f, .65f, 1f, 1f);\n\n        notePanel = NewPanel(canvas.transform, \"World Note Panel\", new Vector2(.20f, .20f), new Vector2(.80f, .80f), new Color(.035f, .025f, .012f, .96f));\n        noteText = NewText(notePanel.transform, \"Note Text\", \"\", 30, new Vector2(.08f, .10f), new Vector2(.92f, .90f));\n        noteText.alignment = TextAnchor.MiddleCenter;\n        dialoguePanel = NewPanel(canvas.transform, \"Dialogue Panel\", new Vector2(.17f, .045f), new Vector2(.83f, .20f), new Color(.005f, .008f, .015f, .78f));\n        dialogueText = NewText(dialoguePanel.transform, \"Dialogue\", \"\", 27, new Vector2(.04f, .10f), new Vector2(.96f, .90f));\n        dialogueText.alignment = TextAnchor.MiddleCenter;\n        hintText = NewText(canvas.transform, \"Controls Hint\", \"\", 20, new Vector2(.22f, .21f), new Vector2(.78f, .27f));\n        hintText.alignment = TextAnchor.MiddleCenter;\n        mapHintText = NewText(hudRoot.transform, \"Map Guidance\", \"\", 18, new Vector2(.035f, .77f), new Vector2(.78f, .82f));\n        mapHintText.alignment = TextAnchor.UpperLeft;\n        mapHintText.gameObject.SetActive(false);\n\n        hudRoot.SetActive(false);\n        dialoguePanel.SetActive(false);\n        notePanel.SetActive(false);\n        coldOverlay.gameObject.SetActive(false);\n        scareOverlay.gameObject.SetActive(false);\n        CreateEventSystemIfMissing();\n    }\n\n    void CreateEventSystemIfMissing()\n    {\n        if (EventSystem.current != null) return;\n        GameObject eventSystem = new GameObject(\"EventSystem\");\n        eventSystem.AddComponent<EventSystem>();\n        eventSystem.AddComponent<StandaloneInputModule>();\n    }\n\n    Image NewImage(Transform parent, string name, Vector2 min, Vector2 max)\n    {\n        GameObject go = new GameObject(name);\n        go.transform.SetParent(parent, false);\n        Image image = go.AddComponent<Image>();\n        RectTransform rect = image.rectTransform;\n        rect.anchorMin = min;\n        rect.anchorMax = max;\n        rect.offsetMin = Vector2.zero;\n        rect.offsetMax = Vector2.zero;\n        return image;\n    }\n\n    Text NewText(Transform parent, string name, string value, int size, Vector2 min, Vector2 max)\n    {\n        GameObject go = new GameObject(name);\n        go.transform.SetParent(parent, false);\n        Text text = go.AddComponent<Text>();\n        text.text = value;\n        text.font = Resources.GetBuiltinResource<Font>(\"LegacyRuntime.ttf\");\n        text.fontSize = size;\n        text.color = Color.white;\n        text.horizontalOverflow = HorizontalWrapMode.Wrap;\n        text.verticalOverflow = VerticalWrapMode.Truncate;\n        RectTransform rect = text.rectTransform;\n        rect.anchorMin = min;\n        rect.anchorMax = max;\n        rect.offsetMin = Vector2.zero;\n        rect.offsetMax = Vector2.zero;\n        return text;\n    }\n\n    GameObject NewPanel(Transform parent, string name, Vector2 min, Vector2 max, Color color)\n    {\n        Image panel = NewImage(parent, name, min, max);\n        panel.color = color;\n        return panel.gameObject;\n    }\n\n    void CreateCrashLight(Transform target)\n    {\n        GameObject lightObject = new GameObject(\"Crash Site Glow\");\n        lightObject.transform.SetParent(target, false);\n        lightObject.transform.localPosition = Vector3.up * 1.5f;\n        crashLight = lightObject.AddComponent<Light>();\n        crashLight.type = LightType.Point;\n        crashLight.color = new Color(1f, .27f, .07f);\n        crashLight.range = crashLightRange;\n        crashLight.intensity = 0f;\n        crashLight.shadows = LightShadows.None;\n    }\n\n    void CreateIntroHelicopterLight(Transform target)\n    {\n        GameObject lightObject = new GameObject(\"Intro Helicopter Visibility Light\");\n        lightObject.transform.SetParent(target, false);\n        lightObject.transform.localPosition = new Vector3(0f, 1.4f, 0f);\n        introHelicopterLight = lightObject.AddComponent<Light>();\n        introHelicopterLight.type = LightType.Point;\n        introHelicopterLight.color = new Color(.72f, .82f, 1f);\n        introHelicopterLight.range = 42f;\n        introHelicopterLight.intensity = 5f;\n        introHelicopterLight.shadows = LightShadows.None;\n    }\n\n    void CreateMapBoundaryWalls()\n    {\n        if (terrain == null || terrain.terrainData == null) return;\n\n        Vector3 origin = terrain.transform.position;\n        Vector3 size = terrain.terrainData.size;\n        float inset = Mathf.Clamp(mapBoundaryInset, 0f, Mathf.Min(size.x, size.z) * .25f);\n        float wallHeight = Mathf.Max(100f, size.y + 60f);\n        float centerY = origin.y + size.y * .5f;\n        float minX = origin.x + inset;\n        float maxX = origin.x + size.x - inset;\n        float minZ = origin.z + inset;\n        float maxZ = origin.z + size.z - inset;\n        float thickness = Mathf.Max(.5f, mapBoundaryWallThickness);\n        Transform walls = new GameObject(\"Invisible Map Boundary\").transform;\n        walls.SetParent(transform, false);\n\n        AddBoundaryWall(walls, \"North Boundary\", new Vector3((minX + maxX) * .5f, centerY, maxZ), new Vector3(maxX - minX, wallHeight, thickness));\n        AddBoundaryWall(walls, \"South Boundary\", new Vector3((minX + maxX) * .5f, centerY, minZ), new Vector3(maxX - minX, wallHeight, thickness));\n        AddBoundaryWall(walls, \"East Boundary\", new Vector3(maxX, centerY, (minZ + maxZ) * .5f), new Vector3(thickness, wallHeight, maxZ - minZ));\n        AddBoundaryWall(walls, \"West Boundary\", new Vector3(minX, centerY, (minZ + maxZ) * .5f), new Vector3(thickness, wallHeight, maxZ - minZ));\n    }\n\n    void AddBoundaryWall(Transform parent, string wallName, Vector3 position, Vector3 size)\n    {\n        GameObject wall = new GameObject(wallName);\n        wall.transform.SetParent(parent, true);\n        wall.transform.position = position;\n        BoxCollider collider = wall.AddComponent<BoxCollider>();\n        collider.size = size;\n    }\n\n    void CreateCrashFire(Transform target)\n    {\n        Shader flameShader = Shader.Find(\"Universal Render Pipeline/Lit\") ?? Shader.Find(\"Standard\");\n        if (flameShader == null) return;\n        Mesh flameMesh = CreateFlameMesh();\n        for (int i = 0; i < 8; i++)\n        {\n            GameObject flame = new GameObject(\"Crash Flame\");\n            flame.transform.SetParent(target, false);\n            float angle = i * Mathf.PI * 2f / 8f;\n            flame.transform.localPosition = new Vector3(Mathf.Cos(angle) * Random.Range(.45f, 1.3f), .65f + (i % 5) * .3f, Mathf.Sin(angle) * Random.Range(.35f, .95f));\n            flame.transform.localScale = new Vector3(.12f, .28f + (i % 4) * .07f, .12f);\n            flame.AddComponent<MeshFilter>().sharedMesh = flameMesh;\n            MeshRenderer renderer = flame.AddComponent<MeshRenderer>();\n            renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;\n            renderer.receiveShadows = false;\n            Material material = new Material(flameShader);\n            Color glow = Color.Lerp(new Color(1f, .08f, .005f), new Color(1f, .62f, .04f), (i % 3) * .35f);\n            material.color = glow;\n            material.EnableKeyword(\"_EMISSION\");\n            material.SetColor(\"_EmissionColor\", glow * 2.5f);\n            renderer.material = material;\n            fireFlames.Add(flame.transform);\n            flame.SetActive(false);\n        }\n        GameObject particleObject = new GameObject(\"Crash Fire Particles\");\n        particleObject.transform.SetParent(target, false);\n        particleObject.transform.localPosition = new Vector3(0f, 1f, 0f);\n        crashFireParticles = particleObject.AddComponent<ParticleSystem>();\n        var main = crashFireParticles.main;\n        main.loop = true;\n        main.startLifetime = new ParticleSystem.MinMaxCurve(1.0f, 1.8f);\n        main.startSpeed = new ParticleSystem.MinMaxCurve(.7f, 1.8f);\n        main.startSize = new ParticleSystem.MinMaxCurve(.1f, .26f);\n        main.startColor = new ParticleSystem.MinMaxGradient(new Color(1f, .12f, .015f), new Color(1f, .8f, .06f));\n        main.gravityModifier = -.18f;\n        var emission = crashFireParticles.emission;\n        emission.rateOverTime = 70f;\n        var shape = crashFireParticles.shape;\n        shape.shapeType = ParticleSystemShapeType.Cone;\n        shape.angle = 18f;\n        shape.radius = .75f;\n        var rendererParticles = particleObject.GetComponent<ParticleSystemRenderer>();\n        Shader particleShader = Shader.Find(\"Universal Render Pipeline/Particles/Unlit\") ?? Shader.Find(\"Particles/Standard Unlit\");\n        if (particleShader != null)\n        {\n            Material particleMaterial = new Material(particleShader);\n            Texture2D softParticle = CreateSoftParticleTexture();\n            particleMaterial.SetTexture(\"_BaseMap\", softParticle);\n            particleMaterial.SetColor(\"_BaseColor\", Color.white);\n            particleMaterial.SetFloat(\"_Surface\", 1f);\n            particleMaterial.SetFloat(\"_Blend\", 0f);\n            particleMaterial.SetFloat(\"_SrcBlend\", (float)UnityEngine.Rendering.BlendMode.SrcAlpha);\n            particleMaterial.SetFloat(\"_DstBlend\", (float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);\n            particleMaterial.SetFloat(\"_ZWrite\", 0f);\n            particleMaterial.EnableKeyword(\"_SURFACE_TYPE_TRANSPARENT\");\n            particleMaterial.renderQueue = 3000;\n            rendererParticles.material = particleMaterial;\n        }\n        crashFireParticles.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);\n    }\n\n    Texture2D CreateSoftParticleTexture()\n    {\n        const int size = 32;\n        Texture2D texture = new Texture2D(size, size, TextureFormat.RGBA32, false);\n        texture.name = \"Runtime Soft Fire Particle\";\n        texture.wrapMode = TextureWrapMode.Clamp;\n        for (int y = 0; y < size; y++)\n        for (int x = 0; x < size; x++)\n        {\n            float dx = (x + .5f) / size * 2f - 1f;\n            float dy = (y + .5f) / size;\n            float horizontal = (x + .5f) / size * 2f - 1f;\n            float width = Mathf.Lerp(.12f, .72f, dy) * (1f - dy * .38f);\n            float edge = Mathf.Clamp01((width - Mathf.Abs(horizontal)) * size * .22f);\n            float alpha = edge * Mathf.Clamp01(dy * 5f) * Mathf.Clamp01((1f - dy) * 3f);\n            texture.SetPixel(x, y, new Color(1f, 1f, 1f, alpha));\n        }\n        texture.Apply();\n        return texture;\n    }\n\n    Mesh CreateFlameMesh()\n    {\n        const int sides = 8;\n        Vector3[] vertices = new Vector3[sides + 1];\n        int[] triangles = new int[sides * 3];\n        for (int i = 0; i < sides; i++)\n        {\n            float angle = i * Mathf.PI * 2f / sides;\n            vertices[i] = new Vector3(Mathf.Cos(angle) * .5f, 0f, Mathf.Sin(angle) * .5f);\n            triangles[i * 3] = i;\n            triangles[i * 3 + 1] = sides;\n            triangles[i * 3 + 2] = (i + 1) % sides;\n        }\n        vertices[sides] = new Vector3(.04f, 1f, 0f);\n        Mesh mesh = new Mesh { name = \"Stylized Flame Mesh\", vertices = vertices, triangles = triangles };\n        mesh.RecalculateNormals();\n        mesh.RecalculateBounds();\n        return mesh;\n    }\n\n    void Update()\n    {\n        if (phase == Phase.Level1 && (!RenderSettings.fog || Mathf.Abs(RenderSettings.fogDensity - levelOneFogDensity) > .0001f))\n            ApplyLevelOneDarkness();\n        AnimateFire();\n        UpdateColdAndJumpscareEffects();\n\n        if (phase == Phase.Title)\n        {\n            if (Input.anyKeyDown) StartCoroutine(OpeningCutscene());\n            return;\n        }\n        if (phase == Phase.Cutscene)\n        {\n            if (Input.GetKeyDown(KeyCode.Alpha1)) skipCutscene = true;\n            if (playerCamera != null) LookAround();\n            return;\n        }\n        if (Input.GetKeyDown(KeyCode.P) && CanSkipCurrentLevel())\n        {\n            SkipCurrentLevel();\n            return;\n        }\n        if (phase == Phase.GameOver || phase == Phase.Complete || phase == Phase.FinalEnding || phase == Phase.CampaignTransition) return;\n        if (noteOpen)\n        {\n            if (Input.GetKeyDown(KeyCode.R)) CloseWorldNote();\n            return;\n        }\n        UpdateWorldNoteHint();\n        if (Input.GetKeyDown(KeyCode.R)) TryReadWorldNote();\n        if (phase == Phase.Level3 && Input.GetKeyDown(KeyCode.F)) ToggleCampaignMap();\n        if (Input.GetKeyDown(KeyCode.E)) HandleFlashlightInput();\n        if (Input.GetKeyDown(KeyCode.Q)) UseMatch();\n        if (Input.GetKeyDown(KeyCode.T)) TryFireGun();\n\n        UpdateHypothermia();\n        if (phase == Phase.GameOver) return;\n        UpdatePickupsAndHelicopter();\n        if (phase == Phase.GameOver || phase == Phase.Complete) return;\n        UpdateCampaignMatchDrops();\n        UpdateWoodRescueSpawn();\n        UpdateCoyoteEncounter();\n        UpdateCampaignRuntime();\n        UpdateHud();\n    }\n\n    void LateUpdate()\n    {\n        if (playerCamera == null || !IsPlaying) return;\n        float coldShake = hypothermia < coldWarningThreshold ? (1f - hypothermia / coldWarningThreshold) : 0f;\n        float chaseShake = coyoteChasing ? .1f : 0f;\n        float shake = Mathf.Max(coldShake * .12f, chaseShake);\n        playerCamera.localPosition = cameraBaseLocalPosition + (shake > 0f ? Random.insideUnitSphere * shake : Vector3.zero);\n    }\n\n    IEnumerator OpeningCutscene()\n    {\n        phase = Phase.Cutscene;\n        titleBackground.gameObject.SetActive(false);\n        titleText.gameObject.SetActive(false);\n        startPrompt.gameObject.SetActive(false);\n        dialoguePanel.SetActive(true);\n        dialogueText.text = \"\";\n\n        string[] lines = {\n            \"Hey, kid, are you doing okay?\",\n            \"It’s been a long flight, huh?\",\n            \"It’s night right now, but don’t worry.\",\n            \"We’re almost there.\",\n            \"Below you is the island of Darael, once known for worshipping the god—\",\n            \"Shit! I think we hit a bird!\",\n            \"Don’t worry. I think everything is under control.\",\n            \"Don’t worry, kid. We have a fire extinguisher.\",\n            \"Well, um…\",\n            \"I think we need to hold on.\",\n            \"Don’t worry!\",\n            \"Stay calm!\"\n        };\n\n        for (int i = 0; i < lines.Length && !skipCutscene; i++)\n        {\n            dialogueText.text = lines[i];\n            if (i >= 4)\n            {\n                fireLevel = Mathf.Min(fireFlames.Count, 1f + (i - 4) * 1.5f);\n                if (crashLight != null) crashLight.intensity = Mathf.Min(crashLightIntensity, 1f + (i - 4) * .8f);\n            }\n            if (i >= 5) StartCoroutine(ShakeHelicopter(i >= 8 ? 1.7f : .55f, 2.5f));\n            float duration = Mathf.Max(3.7f, lines[i].Length * .065f);\n            float elapsed = 0f;\n            while (elapsed < duration && !skipCutscene)\n            {\n                if (playerCamera != null && helicopter != null)\n                    playerCamera.position = Vector3.Lerp(playerCamera.position, helicopter.position - helicopter.forward * 10f + Vector3.up * 4f, Time.deltaTime * .35f);\n                LookAround();\n                elapsed += Time.deltaTime;\n                yield return null;\n            }\n        }\n\n        if (!skipCutscene)\n        {\n            blackoutOverlay.gameObject.SetActive(true);\n            blackoutOverlay.color = Color.black;\n            PlaceCrashScene();\n            yield return new WaitForSeconds(5f);\n            if (playerCamera != null)\n            {\n                playerCamera.SetParent(player, false);\n                playerCamera.localPosition = new Vector3(0f, 1.5f, 0f);\n                playerCamera.localRotation = Quaternion.Euler(-8f, 0f, 0f);\n                cameraBaseLocalPosition = playerCamera.localPosition;\n            }\n            yield return FadeFromBlack(1.5f);\n        }\n        else\n        {\n            PlaceCrashScene();\n            if (playerCamera != null)\n            {\n                playerCamera.SetParent(player, false);\n                playerCamera.localPosition = new Vector3(0f, 1.5f, 0f);\n                playerCamera.localRotation = Quaternion.Euler(-8f, 0f, 0f);\n                cameraBaseLocalPosition = playerCamera.localPosition;\n            }\n            blackoutOverlay.gameObject.SetActive(false);\n        }\n\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        string[] kidLines = { \"Hello?\", \"Are you there?\", \"Pilot?!\" };\n        foreach (string line in kidLines)\n        {\n            dialogueText.text = line;\n            yield return new WaitForSeconds(Mathf.Max(2.5f, line.Length * .15f));\n        }\n        BeginTutorial2();\n    }\n\n    void PlaceCrashScene()\n    {\n        if (helicopter != null)\n        {\n            Vector3 landing = helicopter.position;\n            if (terrain != null) landing.y = terrain.SampleHeight(landing) + terrain.transform.position.y + 1.2f;\n            helicopter.position = landing;\n            helicopter.rotation = Quaternion.Euler(0f, helicopter.eulerAngles.y, 18f);\n        }\n        foreach (Renderer renderer in hiddenForFlight) if (renderer != null) renderer.enabled = true;\n        hiddenForFlight.Clear();\n        ClearCrashLandingSightline();\n        fireLevel = fireFlames.Count;\n        if (crashLight != null) crashLight.intensity = crashLightIntensity;\n        if (helicopter != null)\n        {\n            player.position = helicopter.position + helicopter.forward * 9f + Vector3.up;\n            player.rotation = Quaternion.LookRotation(-helicopter.forward, Vector3.up);\n        }\n        if (playerCamera != null)\n        {\n            Camera cam = playerCamera.GetComponent<Camera>();\n            if (cam != null)\n            {\n                cam.clearFlags = savedCameraClearFlags;\n                cam.backgroundColor = savedCameraBackground;\n            }\n        }\n        RenderSettings.fog = true;\n        RenderSettings.fogMode = FogMode.Exponential;\n        RenderSettings.fogDensity = crashFogDensity;\n        RenderSettings.fogColor = new Color(.012f, .018f, .032f, 1f);\n        if (introHelicopterLight != null) introHelicopterLight.enabled = false;\n        crashCheckpoint = player.position;\n        crashCheckpointRotation = player.rotation;\n        hypothermia = startingHypothermia;\n        matches = startingMatches;\n        IsPlaying = false;\n    }\n\n    void BeginTutorial2()\n    {\n        dialogueText.text = \"I need to add wood to the helicopter fire!\";\n        dialoguePanel.SetActive(true);\n        hudRoot.SetActive(true);\n        phase = Phase.TutorialWood;\n        IsPlaying = true;\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        SpawnWood(player.position + player.forward * 3.5f, true);\n        hintText.text = \"Collect the firewood, then bring it to the helicopter.\";\n        UpdateHud();\n    }\n\n    void BeginTutorialFlashlight()\n    {\n        phase = Phase.TutorialFlashlight;\n        dialogueText.text = \"I need to explore and find more wood. Geez, it’s dark. I need to turn on my flashlight.\";\n        hintText.text = \"Press E to turn on the flashlight.\";\n        UpdateHud();\n    }\n\n    void HandleFlashlightInput()\n    {\n        if (flashlight != null) flashlight.enabled = !flashlight.enabled;\n        if (flashlightToggleSound != null) audioSource.PlayOneShot(flashlightToggleSound, .55f);\n        if (activeCoyote != null)\n        {\n            if (!coyoteEscaping && IsCoyoteInFlashCone())\n            {\n                coyoteFlashHits++;\n                hintText.text = \"Keep flashing your light at the coyote!\";\n                int flashesNeeded = coyoteChasing ? chasingFlashesToScareCoyote : flashesToScareCoyote;\n                if (coyoteFlashHits >= flashesNeeded) ScareCoyoteAway();\n            }\n            else hintText.text = \"Aim at the coyote and flash quickly!\";\n        }\n        else if (phase == Phase.TutorialFlashlight && flashlight != null && flashlight.enabled)\n        {\n            phase = Phase.TutorialCold;\n            hypothermia = tutorialColdStart;\n            coldWarningShown = false;\n            dialogueText.text = \"Geez, it’s freezing. I need to go back to the helicopter to stay warm, or I could use a match.\";\n            hintText.text = \"Hypothermia drains over time. Press Q to use a match and warm up.\";\n        }\n        UpdateHud();\n    }\n\n    bool IsCoyoteInFlashCone()\n    {\n        if (activeCoyote == null || playerCamera == null) return false;\n        Vector3 target = activeCoyote.position + Vector3.up * .8f;\n        Vector3 toCoyote = target - playerCamera.position;\n        if (toCoyote.magnitude > flashlightRange + 2f) return false;\n        return Vector3.Angle(playerCamera.forward, toCoyote) <= coyoteFlashAngle * .5f;\n    }\n\n    void UseMatch()\n    {\n        if (matches <= 0)\n        {\n            hintText.text = \"You have no matches left. Return to the helicopter to warm up.\";\n            return;\n        }\n        matches--;\n        hypothermia = Mathf.Min(100f, hypothermia + matchResetAmount);\n        if (phase == Phase.TutorialCold)\n        {\n            dialogueText.text = \"That helped. I need to keep moving and stay alert.\";\n            hintText.text = \"A Coyote! Flash your light at it by pressing E repeatedly.\";\n            phase = Phase.TutorialCoyote;\n            SpawnCoyote(true);\n        }\n        UpdateHud();\n    }\n\n    void UpdateHypothermia()\n    {\n        if (phase != Phase.TutorialCold && phase != Phase.TutorialCoyote && phase != Phase.Level1 && phase != Phase.Level2 && phase != Phase.Level3) return;\n        if (helicopter != null && Vector3.Distance(player.position, helicopter.position) <= helicopterWarmthRadius)\n        {\n            hypothermia = startingHypothermia;\n            coldWarningShown = false;\n            if (phase == Phase.Level1) hintText.text = \"The helicopter keeps you warm.\";\n        }\n        else\n        {\n            float drain = phase == Phase.TutorialCold ? tutorialHypothermiaDrainPerSecond : hypothermiaDrainPerSecond;\n            if (phase == Phase.Level3) drain *= jacketColdDrainMultiplier;\n            hypothermia = Mathf.Max(0f, hypothermia - drain * Time.deltaTime);\n        }\n\n        UpdateHypothermiaBar();\n\n        bool shouldPlayBreathing = hypothermia <= coldWarningThreshold && hypothermia > 0f;\n        if (breathingAudioSource != null && breathingAudioSource.clip != null)\n        {\n            if (shouldPlayBreathing && !breathingAudioSource.isPlaying) breathingAudioSource.Play();\n            else if (!shouldPlayBreathing && breathingAudioSource.isPlaying) breathingAudioSource.Stop();\n        }\n\n        if (hypothermia <= coldWarningThreshold && !coldWarningShown)\n        {\n            coldWarningShown = true;\n            if (phase == Phase.TutorialCold)\n            {\n                dialogueText.text = \"I’m freezing! I need to use a match or get back to the helicopter.\";\n                hintText.text = \"Press Q to use a match.\";\n            }\n        }\n        if (hypothermia <= 0f) ShowGameOver(\"You froze to death.\");\n    }\n\n    void UpdatePickupsAndHelicopter()\n    {\n        for (int i = matchPickups.Count - 1; i >= 0; i--)\n        {\n            MatchPickup pickup = matchPickups[i];\n            if (pickup.root == null) { matchPickups.RemoveAt(i); continue; }\n            if (HorizontalDistance(player.position, pickup.root.transform.position) <= matchPickupDistance)\n            {\n                matches += matchesPerPickup;\n                Destroy(pickup.root);\n                matchPickups.RemoveAt(i);\n                hintText.text = \"You found more matches.\";\n                UpdateHud();\n            }\n        }\n        for (int i = notePickups.Count - 1; i >= 0; i--)\n            if (notePickups[i].root == null) notePickups.RemoveAt(i);\n\n        for (int i = woodPickups.Count - 1; i >= 0; i--)\n        {\n            WoodPickup pickup = woodPickups[i];\n            if (pickup.root == null) { woodPickups.RemoveAt(i); continue; }\n            float pickupDistance = HorizontalDistance(player.position, pickup.root.transform.position);\n            if (!pickup.chimePlayed && pickupDistance <= woodChimeDistance)\n            {\n                pickup.chimePlayed = true;\n                if (woodPickupChime != null) audioSource.PlayOneShot(woodPickupChime, .65f);\n            }\n            if (pickupDistance <= woodPickupDistance)\n            {\n                woodCarried++;\n                if (phase == Phase.Level1) woodRescueTimer = woodRescueSpawnDelay;\n                Destroy(pickup.root);\n                woodPickups.RemoveAt(i);\n                if (pickup.tutorial)\n                {\n                    phase = Phase.TutorialDeliver;\n                    dialogueText.text = \"I need to add this wood to the fire!\";\n                    hintText.text = \"Return to the helicopter to add the wood to the fire.\";\n                }\n            }\n        }\n\n        if (woodCarried > 0 && helicopter != null && HorizontalDistance(player.position, helicopter.position) <= helicopterDepositDistance)\n        {\n            woodDelivered += woodCarried;\n            woodCarried = 0;\n            if (phase == Phase.TutorialDeliver)\n            {\n                woodDelivered = 1;\n                BeginTutorialFlashlight();\n            }\n            else if (phase == Phase.Level1 && woodDelivered >= 1 + levelOneAdditionalWood)\n            {\n                BeginLevelTwoIntro();\n            }\n        }\n\n        if ((phase == Phase.TutorialCold || phase == Phase.TutorialCoyote || phase == Phase.Level1 || phase == Phase.Level2 || phase == Phase.Level3) && helicopter != null && HorizontalDistance(player.position, helicopter.position) <= helicopterWarmthRadius)\n            hypothermia = startingHypothermia;\n    }\n\n    float HorizontalDistance(Vector3 a, Vector3 b)\n    {\n        a.y = 0f;\n        b.y = 0f;\n        return Vector3.Distance(a, b);\n    }\n\n    void BeginLevel1()\n    {\n        phase = Phase.Level1;\n        levelOneCheckpoint = player.position;\n        levelOneCheckpointRotation = player.rotation;\n        woodDelivered = 1;\n        woodCarried = 0;\n        matches = startingMatches;\n        hypothermia = startingHypothermia;\n        woodRescueTimer = woodRescueSpawnDelay;\n        coldWarningShown = false;\n        levelCoyoteTimer = GetNextCoyoteSpawnDelay();\n        SpawnRemainingLevelWood();\n        SpawnLevelMatchPickups();\n        SpawnLevelNotes();\n        ApplyLevelOneDarkness();\n        dialogueText.text = \"\";\n        dialoguePanel.SetActive(false);\n        hintText.text = \"Level 1: collect 14 more pieces, then return to the helicopter.\";\n        IsPlaying = true;\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        UpdateHud();\n    }\n\n    void SpawnRemainingLevelWood()\n    {\n        int totalRequired = 1 + levelOneAdditionalWood;\n        int remaining = Mathf.Max(0, totalRequired - woodDelivered);\n        for (int i = 0; i < remaining; i++) SpawnLevelWood();\n    }\n\n    void SpawnLevelWood()\n    {\n        Vector3 origin = helicopter != null ? helicopter.position : player.position;\n        Vector3 position = origin;\n        bool foundSeparatedPosition = false;\n        for (int attempt = 0; attempt < 80; attempt++)\n        {\n            Vector2 offset = Random.insideUnitCircle.normalized * Random.Range(woodSpawnMinRadius, woodSpawnMaxRadius);\n            Vector3 candidate = ClampToTerrain(origin + new Vector3(offset.x, 0f, offset.y));\n            bool separated = true;\n            foreach (WoodPickup existing in woodPickups)\n                if (existing.root != null && Vector3.Distance(candidate, existing.root.transform.position) < woodMinimumSeparation)\n                {\n                    separated = false;\n                    break;\n                }\n            if (separated)\n            {\n                position = candidate;\n                foundSeparatedPosition = true;\n                break;\n            }\n        }\n        if (!foundSeparatedPosition)\n            Debug.LogWarning(\"Could not place this firewood pickup with the requested spacing. Increase the spawn radius or reduce minimum separation.\");\n        SpawnWood(position, false);\n    }\n\n    void SpawnLevelMatchPickups()\n    {\n        for (int i = 0; i < levelOneMatchPickupCount; i++)\n        {\n            Vector3 position = FindPickupPosition(matchPickups.ConvertAll(p => p.root), woodMinimumSeparation, matchMinimumSeparation);\n            SpawnMatchPickup(position);\n        }\n    }\n\n    float GetCampaignMatchSpawnDelay(Phase forPhase)\n    {\n        float minDelay = forPhase == Phase.Level2 ? levelTwoMatchSpawnMinDelay : levelThreeMatchSpawnMinDelay;\n        float maxDelay = forPhase == Phase.Level2 ? levelTwoMatchSpawnMaxDelay : levelThreeMatchSpawnMaxDelay;\n        minDelay = Mathf.Max(1f, Mathf.Min(minDelay, maxDelay));\n        maxDelay = Mathf.Max(minDelay, Mathf.Max(minDelay, maxDelay));\n        return Random.Range(minDelay, maxDelay);\n    }\n\n    void UpdateCampaignMatchDrops()\n    {\n        if (phase != Phase.Level2 && phase != Phase.Level3) return;\n        int activePickups = 0;\n        foreach (MatchPickup pickup in matchPickups)\n            if (pickup.root != null) activePickups++;\n        if (activePickups >= Mathf.Max(1, maxCampaignMatchPickups)) return;\n        campaignMatchSpawnTimer -= Time.deltaTime;\n        if (campaignMatchSpawnTimer > 0f) return;\n        SpawnCampaignMatchNearPlayer();\n        campaignMatchSpawnTimer = GetCampaignMatchSpawnDelay(phase);\n    }\n\n    void SpawnCampaignMatchNearPlayer()\n    {\n        Vector3 position = player.position;\n        float minDistance = Mathf.Max(4f, campaignMatchSpawnMinDistance);\n        float maxDistance = Mathf.Max(minDistance + 1f, campaignMatchSpawnMaxDistance);\n        for (int attempt = 0; attempt < 80; attempt++)\n        {\n            Vector2 offset = Random.insideUnitCircle.normalized * Random.Range(minDistance, maxDistance);\n            Vector3 candidate = ClampToTerrain(player.position + new Vector3(offset.x, 0f, offset.y));\n            bool separated = HorizontalDistance(candidate, player.position) >= minDistance * .75f;\n            foreach (MatchPickup pickup in matchPickups)\n                if (pickup.root != null && Vector3.Distance(candidate, pickup.root.transform.position) < matchMinimumSeparation) { separated = false; break; }\n            if (!separated) continue;\n            position = candidate;\n            break;\n        }\n        SpawnMatchPickup(position);\n        hintText.text = \"You hear a faint match rattle somewhere nearby.\";\n    }\n\n    void SpawnLevelNotes()\n    {\n        int count = Mathf.Min(levelOneNoteCount, worldNotes != null ? worldNotes.Count : 0);\n        for (int i = 0; i < count; i++)\n        {\n            Vector3 position = FindPickupPosition(notePickups.ConvertAll(p => p.root), woodMinimumSeparation, 10f);\n            SpawnWorldNote(position, worldNotes[i]);\n        }\n    }\n\n    Vector3 FindPickupPosition(List<GameObject> sameType, float woodSpacing, float ownSpacing)\n    {\n        Vector3 origin = helicopter != null ? helicopter.position : player.position;\n        Vector3 candidate = origin;\n        for (int attempt = 0; attempt < 100; attempt++)\n        {\n            Vector2 offset = Random.insideUnitCircle.normalized * Random.Range(woodSpawnMinRadius, woodSpawnMaxRadius);\n            candidate = ClampToTerrain(origin + new Vector3(offset.x, 0f, offset.y));\n            bool separated = true;\n            foreach (WoodPickup wood in woodPickups)\n                if (wood.root != null && Vector3.Distance(candidate, wood.root.transform.position) < woodSpacing) { separated = false; break; }\n            if (!separated) continue;\n            foreach (GameObject other in sameType)\n                if (other != null && Vector3.Distance(candidate, other.transform.position) < ownSpacing) { separated = false; break; }\n            if (separated) return candidate;\n        }\n        return candidate;\n    }\n\n    void SpawnMatchPickup(Vector3 position)\n    {\n        position = ClampToTerrain(position);\n        GameObject bundle = new GameObject(\"Match Bundle Pickup\");\n        bundle.transform.position = position;\n        // Three small crossed matchsticks give this pickup a distinct silhouette from the single firewood log.\n        for (int i = 0; i < 3; i++)\n        {\n            GameObject stick = GameObject.CreatePrimitive(PrimitiveType.Cylinder);\n            stick.name = \"Matchstick\";\n            stick.transform.SetParent(bundle.transform, false);\n            stick.transform.localPosition = new Vector3((i - 1) * .09f, .13f, 0f);\n            stick.transform.localRotation = Quaternion.Euler(0f, i * 60f, 90f);\n            stick.transform.localScale = new Vector3(.025f, .16f, .025f);\n            Collider c = stick.GetComponent<Collider>(); if (c != null) Destroy(c);\n            SetPickupMaterial(stick.GetComponent<Renderer>(), new Color(.82f, .66f, .32f), new Color(.65f, .33f, .06f));\n            GameObject head = GameObject.CreatePrimitive(PrimitiveType.Sphere);\n            head.name = \"Red Match Head\";\n            head.transform.SetParent(stick.transform, false);\n            head.transform.localPosition = new Vector3(0f, .92f, 0f);\n            head.transform.localScale = Vector3.one * 1.15f;\n            Collider hc = head.GetComponent<Collider>(); if (hc != null) Destroy(hc);\n            SetPickupMaterial(head.GetComponent<Renderer>(), new Color(.75f, .08f, .025f), new Color(1f, .12f, .015f));\n        }\n        AddPickupMarker(bundle.transform, new Color(1f, .25f, .08f), matchMarkerLightIntensity, matchMarkerLightRange, \"Match Ember Glow\");\n        matchPickups.Add(new MatchPickup { root = bundle });\n    }\n\n    void SpawnWorldNote(Vector3 position, string text)\n    {\n        position = ClampToTerrain(position);\n        GameObject note = GameObject.CreatePrimitive(PrimitiveType.Cube);\n        note.name = \"Readable Note\";\n        note.transform.position = position + Vector3.up * .24f;\n        note.transform.rotation = Quaternion.Euler(0f, Random.Range(0f, 360f), Random.Range(-8f, 8f));\n        note.transform.localScale = new Vector3(.34f, .035f, .42f);\n        Collider c = note.GetComponent<Collider>(); if (c != null) Destroy(c);\n        SetPickupMaterial(note.GetComponent<Renderer>(), new Color(.78f, .68f, .46f), new Color(.23f, .14f, .04f));\n        // Dark ink lines distinguish a paper note from both the brown log and red-headed match bundle.\n        for (int i = 0; i < 3; i++)\n        {\n            GameObject line = GameObject.CreatePrimitive(PrimitiveType.Cube);\n            line.name = \"Ink Line\";\n            line.transform.SetParent(note.transform, false);\n            line.transform.localPosition = new Vector3(0f, .56f, -.22f + i * .15f);\n            line.transform.localScale = new Vector3(.72f, .05f, .035f);\n            Collider lc = line.GetComponent<Collider>(); if (lc != null) Destroy(lc);\n            SetPickupMaterial(line.GetComponent<Renderer>(), new Color(.13f, .09f, .055f), Color.black);\n        }\n        AddPickupMarker(note.transform, new Color(.72f, .82f, 1f), .45f, 2.6f, \"Note Marker Glow\");\n        notePickups.Add(new WorldNotePickup { root = note, text = text });\n    }\n\n    void SetPickupMaterial(Renderer renderer, Color color, Color emission)\n    {\n        if (renderer == null) return;\n        Shader shader = Shader.Find(\"Universal Render Pipeline/Lit\") ?? Shader.Find(\"Standard\");\n        if (shader == null) return;\n        Material material = new Material(shader);\n        material.color = color;\n        material.EnableKeyword(\"_EMISSION\");\n        material.SetColor(\"_EmissionColor\", emission * .4f);\n        renderer.material = material;\n    }\n\n    void AddPickupMarker(Transform parent, Color color, float intensity, float range, string name)\n    {\n        GameObject marker = new GameObject(name);\n        marker.transform.SetParent(parent, false);\n        marker.transform.localPosition = Vector3.up * .3f;\n        Light light = marker.AddComponent<Light>();\n        light.type = LightType.Point;\n        light.color = color;\n        light.intensity = intensity;\n        light.range = range;\n        light.shadows = LightShadows.None;\n    }\n\n    void TryReadWorldNote()\n    {\n        WorldNotePickup nearest = null;\n        float nearestDistance = noteReadDistance;\n        foreach (WorldNotePickup note in notePickups)\n        {\n            if (note.root == null) continue;\n            float d = Vector3.Distance(player.position, note.root.transform.position);\n            if (d < nearestDistance) { nearest = note; nearestDistance = d; }\n        }\n        if (nearest == null) return;\n        if (mapOpen) ToggleCampaignMap();\n        if (nearest.campaignNote)\n        {\n            if (nearest.root != null) Destroy(nearest.root);\n            notePickups.Remove(nearest);\n            RegisterCampaignNoteFound(nearest.campaignIndex);\n        }\n        noteOpen = true;\n        movementWasEnabledBeforeNote = movement != null && movement.enabled;\n        if (movement != null) movement.enabled = false;\n        noteText.text = nearest.text + \"\\n\\n[ R ] CLOSE\";\n        notePanel.SetActive(true);\n        hintText.text = \"Reading note — press R to close.\";\n    }\n\n    void CloseWorldNote()\n    {\n        noteOpen = false;\n        if (notePanel != null) notePanel.SetActive(false);\n        if (movement != null) movement.enabled = movementWasEnabledBeforeNote;\n        if (AdvanceToLevelFourAfterNoteCloses()) StartCoroutine(BeginLevelFourSequence());\n    }\n\n    void UpdateWorldNoteHint()\n    {\n        foreach (WorldNotePickup note in notePickups)\n        {\n            if (note.root != null && Vector3.Distance(player.position, note.root.transform.position) <= noteReadDistance)\n            {\n                hintText.text = \"Press R to read the note.\";\n                return;\n            }\n        }\n        if (hintText.text == \"Press R to read the note.\") hintText.text = \"\";\n    }\n\n    void UpdateWoodRescueSpawn()\n    {\n        if (phase != Phase.Level1) return;\n        if (woodDelivered + woodCarried >= 1 + levelOneAdditionalWood) return;\n        woodRescueTimer -= Time.deltaTime;\n        if (woodRescueTimer > 0f) return;\n\n        woodRescueTimer = woodRescueSpawnDelay;\n        Vector3 origin = player.position;\n        Vector3 horizontal = Random.insideUnitSphere;\n        horizontal.y = 0f;\n        if (horizontal.sqrMagnitude < .01f) horizontal = player.forward;\n        Vector3 position = origin + horizontal.normalized * Random.Range(woodRescueSpawnMinDistance, woodRescueSpawnMaxDistance);\n        position = ClampToTerrain(position);\n        foreach (WoodPickup existing in woodPickups)\n        {\n            if (existing.root != null && Vector3.Distance(position, existing.root.transform.position) < woodMinimumSeparation * .5f)\n            {\n                Vector3 right = Vector3.Cross(Vector3.up, player.forward).normalized;\n                position = ClampToTerrain(origin + right * Random.Range(woodRescueSpawnMinDistance, woodRescueSpawnMaxDistance));\n                break;\n            }\n        }\n        SpawnWood(position, false);\n        hintText.text = \"You hear a faint chime nearby.\";\n    }\n\n    Vector3 ClampToTerrain(Vector3 position)\n    {\n        if (terrain == null) return position;\n        Vector3 terrainOrigin = terrain.transform.position;\n        Vector3 size = terrain.terrainData.size;\n        position.x = Mathf.Clamp(position.x, terrainOrigin.x + 3f, terrainOrigin.x + size.x - 3f);\n        position.z = Mathf.Clamp(position.z, terrainOrigin.z + 3f, terrainOrigin.z + size.z - 3f);\n        position.y = terrain.SampleHeight(position) + terrainOrigin.y + .35f;\n        return position;\n    }\n\n    void SpawnWood(Vector3 position, bool tutorial)\n    {\n        position = ClampToTerrain(position);\n        GameObject wood = GameObject.CreatePrimitive(PrimitiveType.Cylinder);\n        wood.name = tutorial ? \"Tutorial Firewood\" : \"Firewood Pickup\";\n        wood.transform.position = position;\n        wood.transform.rotation = Quaternion.Euler(0f, Random.Range(0f, 360f), 90f);\n        wood.transform.localScale = new Vector3(.075f, .22f, .075f);\n        Collider collider = wood.GetComponent<Collider>();\n        if (collider != null) Destroy(collider);\n        Renderer renderer = wood.GetComponent<Renderer>();\n        Shader shader = Shader.Find(\"Universal Render Pipeline/Lit\") ?? Shader.Find(\"Standard\");\n        if (shader != null)\n        {\n            Material material = new Material(shader);\n            material.color = new Color(.34f, .15f, .055f);\n            material.EnableKeyword(\"_EMISSION\");\n            material.SetColor(\"_EmissionColor\", new Color(.35f, .14f, .025f) * 1.3f);\n            renderer.material = material;\n        }\n        GameObject marker = new GameObject(\"Firewood Marker Glow\");\n        marker.transform.SetParent(wood.transform, false);\n        marker.transform.localPosition = Vector3.up * .12f;\n        Light markerLight = marker.AddComponent<Light>();\n        markerLight.type = LightType.Point;\n        markerLight.color = new Color(1f, .62f, .24f);\n        markerLight.range = woodMarkerLightRange;\n        markerLight.intensity = woodMarkerLightIntensity;\n        markerLight.shadows = LightShadows.None;\n        woodPickups.Add(new WoodPickup { root = wood, tutorial = tutorial });\n    }\n\n    void SpawnCoyote(bool tutorial)\n    {\n        if (activeCoyote != null) return;\n        Vector3 forward = playerCamera != null ? playerCamera.forward : player.forward;\n        forward.y = 0f;\n        if (forward.sqrMagnitude < .01f) forward = player.forward;\n        forward.Normalize();\n        Vector3 right = Vector3.Cross(Vector3.up, forward).normalized;\n        float distance = tutorial ? tutorialCoyoteDistance\n            : phase == Phase.Level4 ? Random.Range(levelFourCoyoteSpawnMinDistance, levelFourCoyoteSpawnMaxDistance)\n            : Random.Range(tutorialCoyoteDistance + 2f, tutorialCoyoteDistance + 12f);\n        float lateralRange = phase == Phase.Level4 ? levelFourCoyoteLateralRange : 4f;\n        Vector3 point = player.position + forward * distance + right * Random.Range(-lateralRange, lateralRange);\n        point = phase == Phase.Level4 ? FindAccessibleNotePoint(point, 8f) : ClampToTerrain(point);\n        GameObject coyote = coyotePrefab != null ? Instantiate(coyotePrefab, point, Quaternion.LookRotation(player.position - point)) : CreateCoyoteStandIn(point);\n        coyote.name = \"Active Coyote\";\n        if (coyote.GetComponent<Collider>() == null)\n        {\n            CapsuleCollider body = coyote.AddComponent<CapsuleCollider>();\n            body.center = new Vector3(0f, .72f, .05f);\n            body.height = 1.45f;\n            body.radius = .42f;\n        }\n        activeCoyote = coyote.transform;\n        coyoteFlashHits = 0;\n        coyoteTimer = !tutorial && phase == Phase.Level2 ? levelTwoCoyoteWarningSeconds\n            : !tutorial && phase == Phase.Level4 ? levelFourCoyoteWarningSeconds\n            : coyoteWarningSeconds;\n        coyoteChasing = false;\n        coyoteEscaping = false;\n        if (coyoteAudioSource != null && coyoteAudioSource.clip != null) coyoteAudioSource.Play();\n        PlayCoyoteSound();\n    }\n\n    GameObject CreateCoyoteStandIn(Vector3 position)\n    {\n        GameObject root = new GameObject(\"Coyote Stand-In\");\n        root.transform.position = position;\n        root.transform.rotation = Quaternion.LookRotation(player.position - position);\n        Shader shader = Shader.Find(\"Universal Render Pipeline/Lit\") ?? Shader.Find(\"Standard\");\n        Material fur = CreateMaterial(shader, new Color(.16f, .095f, .07f));\n        Material muzzle = CreateMaterial(shader, new Color(.28f, .17f, .13f));\n        Material eye = CreateMaterial(shader, new Color(1f, .38f, .04f), true);\n        AddCoyotePart(root.transform, PrimitiveType.Capsule, \"Body\", new Vector3(0f, .48f, -.08f), new Vector3(.42f, .36f, .9f), fur);\n        AddCoyotePart(root.transform, PrimitiveType.Sphere, \"Head\", new Vector3(0f, .82f, .48f), new Vector3(.42f, .38f, .42f), fur);\n        AddCoyotePart(root.transform, PrimitiveType.Sphere, \"Muzzle\", new Vector3(0f, .68f, .76f), new Vector3(.26f, .18f, .35f), muzzle);\n        AddCoyotePart(root.transform, PrimitiveType.Cube, \"Ear L\", new Vector3(-.15f, 1.12f, .42f), new Vector3(.12f, .34f, .13f), fur);\n        AddCoyotePart(root.transform, PrimitiveType.Cube, \"Ear R\", new Vector3(.15f, 1.12f, .42f), new Vector3(.12f, .34f, .13f), fur);\n        AddCoyotePart(root.transform, PrimitiveType.Sphere, \"Eye L\", new Vector3(-.16f, .89f, .67f), new Vector3(.07f, .07f, .045f), eye);\n        AddCoyotePart(root.transform, PrimitiveType.Sphere, \"Eye R\", new Vector3(.16f, .89f, .67f), new Vector3(.07f, .07f, .045f), eye);\n        for (int i = 0; i < 4; i++)\n        {\n            float x = i % 2 == 0 ? -.14f : .14f;\n            float z = i < 2 ? .25f : -.38f;\n            AddCoyotePart(root.transform, PrimitiveType.Capsule, \"Leg\", new Vector3(x, .22f, z), new Vector3(.12f, .35f, .13f), fur);\n        }\n        return root;\n    }\n\n    Material CreateMaterial(Shader shader, Color color, bool emissive = false)\n    {\n        if (shader == null) return null;\n        Material material = new Material(shader);\n        material.color = color;\n        if (emissive)\n        {\n            material.EnableKeyword(\"_EMISSION\");\n            material.SetColor(\"_EmissionColor\", color * 2f);\n        }\n        return material;\n    }\n\n    void AddCoyotePart(Transform parent, PrimitiveType type, string name, Vector3 localPosition, Vector3 localScale, Material material)\n    {\n        GameObject part = GameObject.CreatePrimitive(type);\n        part.name = name;\n        part.transform.SetParent(parent, false);\n        part.transform.localPosition = localPosition;\n        part.transform.localScale = localScale;\n        Collider collider = part.GetComponent<Collider>();\n        if (collider != null) Destroy(collider);\n        Renderer renderer = part.GetComponent<Renderer>();\n        if (renderer != null && material != null)\n        {\n            renderer.material = material;\n            renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;\n        }\n    }\n\n    void UpdateCoyoteEncounter()\n    {\n        if (activeCoyote == null)\n        {\n            if (phase == Phase.Level1 || phase == Phase.Level2 || phase == Phase.Level3 || phase == Phase.Level4)\n            {\n                levelCoyoteTimer -= Time.deltaTime;\n                if (levelCoyoteTimer <= 0f)\n                {\n                    SpawnCoyote(false);\n                }\n            }\n            return;\n        }\n\n        if (coyoteEscaping) return;\n        if (!coyoteChasing)\n        {\n            coyoteTimer -= Time.deltaTime;\n            if (coyoteTimer <= 0f) BeginCoyoteChase();\n        }\n        else\n        {\n            Vector3 target = player.position;\n            target.y = activeCoyote.position.y;\n            activeCoyote.position = Vector3.MoveTowards(activeCoyote.position, target, coyoteChaseSpeed * Time.deltaTime);\n            Vector3 look = player.position - activeCoyote.position;\n            look.y = 0f;\n            if (look.sqrMagnitude > .01f) activeCoyote.rotation = Quaternion.LookRotation(look);\n            if (Vector3.Distance(activeCoyote.position, player.position) <= coyoteCatchDistance)\n                ShowGameOver(\"The coyote caught you.\");\n        }\n    }\n\n    void BeginCoyoteChase()\n    {\n        coyoteChasing = true;\n        coyoteFlashHits = 0;\n        hintText.text = \"It’s charging! Keep flashing your light!\";\n    }\n\n    void ScareCoyoteAway()\n    {\n        if (activeCoyote == null || coyoteEscaping) return;\n        coyoteEscaping = true;\n        coyoteChasing = false;\n        StopCoyoteSound();\n        StartCoroutine(CoyoteRunsAway());\n    }\n\n    IEnumerator CoyoteRunsAway()\n    {\n        Transform escapingCoyote = activeCoyote;\n        if (escapingCoyote != null)\n        {\n            Vector3 runDirection = (escapingCoyote.position - player.position).normalized;\n            runDirection.y = 0f;\n            if (runDirection.sqrMagnitude > .01f) escapingCoyote.rotation = Quaternion.LookRotation(runDirection);\n            Vector3 start = escapingCoyote.position;\n            Vector3 end = ClampToTerrain(start + runDirection * 10f);\n            float duration = .9f;\n            float elapsed = 0f;\n            while (elapsed < duration && escapingCoyote != null)\n            {\n                float t = elapsed / duration;\n                escapingCoyote.position = Vector3.Lerp(start, end, t);\n                escapingCoyote.rotation = Quaternion.Slerp(escapingCoyote.rotation, Quaternion.LookRotation(runDirection), Time.deltaTime * 4f);\n                elapsed += Time.deltaTime;\n                yield return null;\n            }\n            if (escapingCoyote != null) Destroy(escapingCoyote.gameObject);\n        }\n        activeCoyote = null;\n        coyoteEscaping = false;\n        if (phase == Phase.TutorialCoyote) BeginLevel1();\n        else if (phase == Phase.Level2IntroCoyote) StartCoroutine(FinishLevelTwoIntro());\n        else\n        {\n            if (phase == Phase.Level2) hintText.text = \"The coyote fled. Listen for the next one.\";\n            else if (phase == Phase.Level3) hintText.text = \"Keep exploring. Follow the notes marked on your map.\";\n            else if (phase == Phase.Level4) hintText.text = \"Keep running. Listen for Coyotes and flash your light when one gets close.\";\n            else hintText.text = \"Keep collecting firewood and watch your hypothermia.\";\n            levelCoyoteTimer = GetNextCoyoteSpawnDelay();\n        }\n    }\n\n    float GetNextCoyoteSpawnDelay()\n    {\n        float minDelay = Mathf.Max(1f, Mathf.Min(coyoteSpawnMinDelay, coyoteSpawnMaxDelay));\n        float maxDelay = Mathf.Max(minDelay, Mathf.Max(coyoteSpawnMinDelay, coyoteSpawnMaxDelay));\n        float delay;\n        if (phase == Phase.Level2)\n        {\n            float levelTwoMin = Mathf.Max(1f, Mathf.Min(levelTwoCoyoteMinDelay, levelTwoCoyoteMaxDelay));\n            float levelTwoMax = Mathf.Max(levelTwoMin, Mathf.Max(levelTwoCoyoteMinDelay, levelTwoCoyoteMaxDelay));\n            delay = Random.Range(levelTwoMin, levelTwoMax) + Mathf.Max(0f, levelTwoCoyoteCooldown);\n        }\n        else if (phase == Phase.Level4)\n        {\n            float levelFourMin = Mathf.Max(1f, Mathf.Min(levelFourCoyoteMinDelay, levelFourCoyoteMaxDelay));\n            float levelFourMax = Mathf.Max(levelFourMin, Mathf.Max(levelFourCoyoteMinDelay, levelFourCoyoteMaxDelay));\n            delay = Random.Range(levelFourMin, levelFourMax) + Mathf.Max(0f, levelFourCoyoteCooldown);\n        }\n        else delay = Random.Range(minDelay, maxDelay) + Mathf.Max(0f, coyoteRespawnDelay);\n        if (phase == Phase.Level3) delay *= Mathf.Max(1f, levelThreeCoyoteDelayMultiplier);\n        return delay;\n    }\n\n    void PlayCoyoteSound()\n    {\n        if (coyoteAudioSource != null && coyoteAudioSource.clip != null && !coyoteAudioSource.isPlaying) coyoteAudioSource.Play();\n    }\n\n    void StopCoyoteSound()\n    {\n        if (coyoteAudioSource != null) coyoteAudioSource.Stop();\n    }\n\n    void AnimateFire()\n    {\n        for (int i = 0; i < fireFlames.Count; i++)\n        {\n            bool visible = fireLevel > i / 3f;\n            Transform flame = fireFlames[i];\n            if (flame == null) continue;\n            if (flame.gameObject.activeSelf != visible) flame.gameObject.SetActive(visible);\n            if (visible)\n            {\n                float flicker = 1f + Mathf.Sin(Time.time * (8f + i) + i) * .13f;\n                flame.localScale = new Vector3(.3f, .6f + (i % 4) * .18f, .3f) * flicker;\n            }\n        }\n        if (crashFireParticles != null)\n        {\n            bool shouldEmit = fireLevel > 0f;\n            var emission = crashFireParticles.emission;\n            emission.enabled = shouldEmit;\n            if (shouldEmit && !crashFireParticles.isPlaying) crashFireParticles.Play();\n            else if (!shouldEmit && crashFireParticles.isPlaying) crashFireParticles.Stop(true, ParticleSystemStopBehavior.StopEmitting);\n        }\n    }\n\n    void UpdateColdAndJumpscareEffects()\n    {\n        float coldAmount = hypothermia < coldWarningThreshold ? 1f - hypothermia / coldWarningThreshold : 0f;\n        coldOverlay.gameObject.SetActive(coldAmount > .01f && (phase == Phase.TutorialCold || phase == Phase.TutorialCoyote || phase == Phase.Level1 || phase == Phase.Level2 || phase == Phase.Level3));\n        coldOverlay.color = new Color(.08f, .28f, 1f, coldAmount * .34f);\n        float scareAmount = coyoteChasing ? .14f + Mathf.PingPong(Time.time * .8f, .2f) : 0f;\n        scareOverlay.gameObject.SetActive(scareAmount > .01f);\n        scareOverlay.color = new Color(.75f, .015f, .025f, scareAmount);\n    }\n\n    void UpdateHud()\n    {\n        if (objectiveText == null) return;\n        int total = 1 + levelOneAdditionalWood;\n        if (phase == Phase.TutorialWood || phase == Phase.TutorialDeliver)\n            objectiveText.text = \"TUTORIAL 2  |  FIREWOOD \" + woodDelivered + \"/\" + total;\n        else if (phase == Phase.TutorialFlashlight || phase == Phase.TutorialCold || phase == Phase.TutorialCoyote)\n            objectiveText.text = \"TUTORIAL 2  |  FIREWOOD \" + woodDelivered + \"/\" + total;\n        else if (phase == Phase.Level1)\n            objectiveText.text = woodDelivered >= total ? \"FIREWOOD \" + total + \"/\" + total + \"  |  RETURN TO THE HELICOPTER\" : \"LEVEL 1  |  FIREWOOD \" + woodDelivered + \"/\" + total;\n        else if (phase == Phase.Level2 || phase == Phase.Level2IntroCoyote)\n            objectiveText.text = \"LEVEL 2  |  COYOTES \" + coyotesKilled + \"/\" + coyotesToKillForJacket;\n        else if (phase == Phase.Level3)\n            objectiveText.text = \"LEVEL 3  |  NOTES \" + levelThreeNotesFound + \"/3  |  \" + FormatCampaignTime(levelThreeDeadlineRemaining);\n        else if (phase == Phase.Level4)\n        {\n            float grace = Mathf.Max(0f, godCatchGraceSeconds - (Time.time - godChaseStartTime));\n            objectiveText.text = grace > 0f\n                ? \"LEVEL 4  |  RUN! \" + Mathf.CeilToInt(grace) + \"s head start\"\n                : \"LEVEL 4  |  RUN TO THE RED LIGHT\";\n        }\n        if (mapHintText != null)\n        {\n            bool showMapHelp = phase == Phase.Level3 && !mapOpen;\n            mapHintText.gameObject.SetActive(showMapHelp);\n            if (showMapHelp) UpdateMapHelpPrompt();\n        }\n        inventoryText.text = \"Inventory: Matches \" + matches + \"   |   Flashlight \" + (flashlight != null && flashlight.enabled ? \"ON\" : \"OFF\") + \"   |   Firewood \" + woodCarried + (gunUnlocked ? \"   |   Fur \" + coyotesKilled : \"\");\n        UpdateHypothermiaBar();\n    }\n\n    void UpdateMapHelpPrompt()\n    {\n        if (mapHintText == null || campaignNotePositions == null) return;\n        int nearest = -1;\n        float nearestDistance = float.MaxValue;\n        for (int i = 0; i < campaignNotePositions.Length; i++)\n        {\n            if (foundCampaignNoteIndices.Contains(i)) continue;\n            float distance = HorizontalDistance(player.position, campaignNotePositions[i]);\n            if (distance < nearestDistance) { nearestDistance = distance; nearest = i; }\n        }\n        string guidance = nearest < 0 ? \"ALL NOTES FOUND\" : GetCompassDirection(campaignNotePositions[nearest] - player.position) + \"  \" + Mathf.RoundToInt(nearestDistance) + \"m\";\n        mapHintText.text = \"PRESS F FOR MAP  |  NEAREST NOTE: \" + guidance + \"  |  PRESS R NEAR A NOTE TO READ\";\n    }\n\n    string GetCompassDirection(Vector3 direction)\n    {\n        float angle = Mathf.Atan2(direction.x, direction.z) * Mathf.Rad2Deg;\n        string[] directions = { \"N\", \"NE\", \"E\", \"SE\", \"S\", \"SW\", \"W\", \"NW\" };\n        int index = Mathf.RoundToInt((angle + 360f) % 360f / 45f) % directions.Length;\n        return directions[index];\n    }\n\n    void UpdateHypothermiaBar()\n    {\n        if (hypothermiaFill == null) return;\n        float maxWarmth = Mathf.Max(1f, startingHypothermia);\n        hypothermiaFill.fillAmount = Mathf.Clamp01(hypothermia / maxWarmth);\n        float coldness = 1f - hypothermiaFill.fillAmount;\n        hypothermiaFill.color = Color.Lerp(new Color(.12f, .58f, 1f, 1f), new Color(.72f, .9f, 1f, 1f), coldness);\n    }\n\n    IEnumerator ShakeHelicopter(float amount, float seconds)\n    {\n        if (helicopter == null) yield break;\n        Vector3 basePosition = helicopter.position;\n        float elapsed = 0f;\n        while (elapsed < seconds && phase == Phase.Cutscene)\n        {\n            helicopter.position = basePosition + Random.insideUnitSphere * amount * .08f;\n            elapsed += Time.deltaTime;\n            yield return null;\n        }\n        if (helicopter != null) helicopter.position = basePosition;\n    }\n\n    IEnumerator FadeFromBlack(float seconds)\n    {\n        blackoutOverlay.gameObject.SetActive(true);\n        float elapsed = 0f;\n        while (elapsed < seconds)\n        {\n            float alpha = 1f - elapsed / seconds;\n            blackoutOverlay.color = new Color(0f, 0f, 0f, alpha);\n            elapsed += Time.deltaTime;\n            yield return null;\n        }\n        blackoutOverlay.gameObject.SetActive(false);\n    }\n\n    void ShowGameOver(string reason)\n    {\n        if (phase == Phase.GameOver) return;\n        phaseBeforeGameOver = phase;\n        bool diedDuringTutorial = phase == Phase.TutorialWood || phase == Phase.TutorialDeliver || phase == Phase.TutorialFlashlight || phase == Phase.TutorialCold || phase == Phase.TutorialCoyote;\n        StopCoyoteSound();\n        if (breathingAudioSource != null) breathingAudioSource.Stop();\n        if (reason.IndexOf(\"coyote\", System.StringComparison.OrdinalIgnoreCase) >= 0 && coyoteJumpscareSound != null)\n            audioSource.PlayOneShot(coyoteJumpscareSound, jumpscareVolume);\n        phase = Phase.GameOver;\n        IsPlaying = false;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        endPanel = NewPanel(canvas.transform, \"Game Over\", Vector2.zero, Vector2.one, new Color(0f, 0f, 0f, .88f));\n        Text title = NewText(endPanel.transform, \"Game Over Title\", \"GAME OVER\\n\" + reason, 38, new Vector2(.15f, .53f), new Vector2(.85f, .74f));\n        title.alignment = TextAnchor.MiddleCenter;\n        string restartLabel = phaseBeforeGameOver == Phase.Level2IntroCoyote ? \"CONTINUE TO LEVEL 2\" : diedDuringTutorial ? \"RESTART TUTORIAL 2\" : \"RESTART CHECKPOINT\";\n        CreateEndButton(endPanel.transform, restartLabel, RestartFromGameOver);\n    }\n\n    void ShowLevelComplete()\n    {\n        phase = Phase.Complete;\n        IsPlaying = false;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        endPanel = NewPanel(canvas.transform, \"Level Complete\", Vector2.zero, Vector2.one, new Color(0f, 0f, 0f, .9f));\n        Text title = NewText(endPanel.transform, \"Level Complete Title\", \"LEVEL 1 COMPLETE\\nLevel 2 is coming soon.\", 36, new Vector2(.12f, .48f), new Vector2(.88f, .72f));\n        title.alignment = TextAnchor.MiddleCenter;\n        CreateEndButton(endPanel.transform, \"REPLAY LEVEL 1\", () => RestartLevelOne(false));\n    }\n\n    void CreateEndButton(Transform parent, string label, UnityEngine.Events.UnityAction action)\n    {\n        GameObject buttonObject = new GameObject(\"Restart Button\");\n        buttonObject.transform.SetParent(parent, false);\n        RectTransform rect = buttonObject.AddComponent<RectTransform>();\n        rect.anchorMin = new Vector2(.36f, .30f);\n        rect.anchorMax = new Vector2(.64f, .39f);\n        rect.offsetMin = Vector2.zero;\n        rect.offsetMax = Vector2.zero;\n        Image image = buttonObject.AddComponent<Image>();\n        image.color = new Color(.55f, .16f, .08f, 1f);\n        Button button = buttonObject.AddComponent<Button>();\n        button.targetGraphic = image;\n        button.onClick.AddListener(action);\n        Text buttonText = NewText(buttonObject.transform, \"Button Label\", label, 24, Vector2.zero, Vector2.one);\n        buttonText.alignment = TextAnchor.MiddleCenter;\n    }\n\n    void RestartTutorial2()\n    {\n        ClearGameplayObjects();\n        if (endPanel != null) Destroy(endPanel);\n        player.position = crashCheckpoint;\n        player.rotation = crashCheckpointRotation;\n        if (playerCamera != null) { playerCamera.SetParent(player, false); playerCamera.localPosition = new Vector3(0f, 1.5f, 0f); cameraBaseLocalPosition = playerCamera.localPosition; playerCamera.localRotation = Quaternion.identity; }\n        if (movement != null) movement.ResetView();\n        ResetCampaignProgress();\n        matches = startingMatches;\n        woodDelivered = 0;\n        woodCarried = 0;\n        hypothermia = startingHypothermia;\n        coldWarningShown = false;\n        if (flashlight != null) flashlight.enabled = false;\n        IsPlaying = false;\n        phase = Phase.TutorialWood;\n        BeginTutorial2();\n    }\n\n    void RestartLevelOne(bool preserveDeliveredProgress)\n    {\n        int savedDeliveredWood = woodDelivered;\n        if (!preserveDeliveredProgress) ResetCampaignProgress();\n        ClearGameplayObjects();\n        if (endPanel != null) Destroy(endPanel);\n        if (movement != null) movement.RestoreDefaultMoveSpeed();\n        player.position = levelOneCheckpoint;\n        player.rotation = levelOneCheckpointRotation;\n        if (playerCamera != null) { playerCamera.SetParent(player, false); playerCamera.localPosition = new Vector3(0f, 1.5f, 0f); cameraBaseLocalPosition = playerCamera.localPosition; playerCamera.localRotation = Quaternion.identity; }\n        if (movement != null) movement.ResetView();\n        if (flashlight != null) flashlight.enabled = false;\n        SetGunVisible(false);\n        matches = startingMatches;\n        woodDelivered = preserveDeliveredProgress ? Mathf.Clamp(savedDeliveredWood, 1, 1 + levelOneAdditionalWood) : 1;\n        woodCarried = 0;\n        hypothermia = startingHypothermia;\n        woodRescueTimer = woodRescueSpawnDelay;\n        coldWarningShown = false;\n        phase = Phase.Level1;\n        IsPlaying = true;\n        levelCoyoteTimer = GetNextCoyoteSpawnDelay();\n        SpawnRemainingLevelWood();\n        SpawnLevelMatchPickups();\n        SpawnLevelNotes();\n        ApplyLevelOneDarkness();\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        dialoguePanel.SetActive(false);\n        hintText.text = \"Level 1: collect 14 more pieces, then return to the helicopter.\";\n        UpdateHud();\n    }\n\n    void ClearGameplayObjects()\n    {\n        StopCoyoteSound();\n        if (breathingAudioSource != null) breathingAudioSource.Stop();\n        foreach (WoodPickup pickup in woodPickups) if (pickup.root != null) Destroy(pickup.root);\n        woodPickups.Clear();\n        foreach (MatchPickup pickup in matchPickups) if (pickup.root != null) Destroy(pickup.root);\n        matchPickups.Clear();\n        foreach (WorldNotePickup note in notePickups) if (note.root != null) Destroy(note.root);\n        notePickups.Clear();\n        noteOpen = false;\n        if (notePanel != null) notePanel.SetActive(false);\n        mapOpen = false;\n        if (campaignMapPanel != null) campaignMapPanel.SetActive(false);\n        if (movement != null && movementWasEnabledBeforeNote) movement.enabled = true;\n        if (movement != null && movementWasEnabledBeforeMap) movement.enabled = true;\n        if (activeCoyote != null) Destroy(activeCoyote.gameObject);\n        activeCoyote = null;\n        coyoteChasing = false;\n        coyoteEscaping = false;\n    }\n\n    void HideFlightForeground(Vector3 center, float radius)\n    {\n        Renderer[] renderers = FindObjectsByType<Renderer>(FindObjectsSortMode.None);\n        foreach (Renderer renderer in renderers)\n        {\n            if (renderer == null || renderer.transform.IsChildOf(player)) continue;\n            // The helicopter is intentionally positioned above the player for the flight shot;\n            // never treat it as foreground terrain just because its horizontal distance is small.\n            if (helicopter != null && (renderer.transform == helicopter || renderer.transform.IsChildOf(helicopter))) continue;\n            if (terrain != null && (renderer.transform == terrain.transform || renderer.transform.IsChildOf(terrain.transform))) continue;\n            Vector3 delta = renderer.bounds.center - center;\n            delta.y = 0f;\n            if (delta.sqrMagnitude <= radius * radius && renderer.bounds.max.y > center.y + 1.5f)\n            {\n                renderer.enabled = false;\n                hiddenForFlight.Add(renderer);\n            }\n        }\n    }\n\n    void ClearCrashLandingSightline()\n    {\n        if (helicopter == null) return;\n        Renderer[] renderers = FindObjectsByType<Renderer>(FindObjectsSortMode.None);\n        foreach (Renderer renderer in renderers)\n        {\n            if (renderer == null || renderer.transform.IsChildOf(player)) continue;\n            if (renderer.transform == helicopter || renderer.transform.IsChildOf(helicopter)) continue;\n            if (terrain != null && (renderer.transform == terrain.transform || renderer.transform.IsChildOf(terrain.transform))) continue;\n            Vector3 horizontalDelta = renderer.bounds.center - helicopter.position;\n            horizontalDelta.y = 0f;\n            float distance = horizontalDelta.magnitude;\n            if (distance > crashLandingClearRadius) continue;\n            bool isTree = false;\n            foreach (Material material in renderer.sharedMaterials)\n            {\n                if (material == null) continue;\n                string materialName = material.name.ToLowerInvariant();\n                if (materialName.Contains(\"bark\") || materialName.Contains(\"birch\") || materialName.Contains(\"ash\") || materialName.Contains(\"leaves\"))\n                {\n                    isTree = true;\n                    break;\n                }\n            }\n            if (!isTree) continue;\n            renderer.enabled = false;\n            hiddenForFlight.Add(renderer);\n        }\n    }\n\n    void ApplyLevelOneDarkness()\n    {\n        RenderSettings.fog = true;\n        RenderSettings.fogMode = FogMode.Exponential;\n        RenderSettings.fogDensity = levelOneFogDensity;\n        RenderSettings.fogColor = new Color(.006f, .009f, .018f, 1f);\n        RenderSettings.ambientIntensity = levelOneAmbientIntensity;\n        if (directionalLight != null) directionalLight.intensity = levelOneDirectionalLightIntensity;\n        if (gameplayCamera != null) gameplayCamera.farClipPlane = levelOneViewDistance;\n        if (crashLight != null)\n        {\n            crashLight.range = levelOneCrashLightRange;\n            crashLight.intensity = levelOneCrashLightIntensity;\n        }\n    }\n\n    void LookAround()\n    {\n        if (Input.GetMouseButtonDown(0)) Cursor.lockState = CursorLockMode.Locked;\n        if (Cursor.lockState != CursorLockMode.Locked && !Input.GetMouseButton(0)) return;\n        lookPitch = Mathf.Clamp(lookPitch - Input.GetAxis(\"Mouse Y\") * 2.5f, -75f, 75f);\n        playerCamera.Rotate(Vector3.up, Input.GetAxis(\"Mouse X\") * 2.5f, Space.World);\n        playerCamera.localEulerAngles = new Vector3(lookPitch, playerCamera.localEulerAngles.y, 0f);\n    }\n\n    void OnGUI()\n    {\n        if (phase != Phase.GameOver && phase != Phase.Complete) return;\n        if (Input.GetKeyDown(KeyCode.R))\n        {\n            if (phase == Phase.Complete) RestartLevelOne(false);\n            else RestartFromGameOver();\n        }\n    }\n\n    void RestartFromGameOver()\n    {\n        if (endPanel != null) Destroy(endPanel);\n        if (phaseBeforeGameOver == Phase.Level2IntroCoyote)\n        {\n            // Do not replay the Coyote encounter that caused this death. Continue the\n            // transition into Level 2 so a cutscene/tutorial death cannot trap the player.\n            ClearGameplayObjects();\n            player.position = levelOneCheckpoint;\n            player.rotation = levelOneCheckpointRotation;\n            hypothermia = startingHypothermia;\n            coldWarningShown = false;\n            phase = Phase.Level2IntroCoyote;\n            StartCoroutine(FinishLevelTwoIntro());\n            return;\n        }\n\n        bool diedDuringTutorial = phaseBeforeGameOver == Phase.TutorialWood\n            || phaseBeforeGameOver == Phase.TutorialDeliver\n            || phaseBeforeGameOver == Phase.TutorialFlashlight\n            || phaseBeforeGameOver == Phase.TutorialCold\n            || phaseBeforeGameOver == Phase.TutorialCoyote;\n        if (diedDuringTutorial) RestartTutorial2();\n        else RestartCampaignCheckpoint();\n    }\n\n    bool CanSkipCurrentLevel()\n    {\n        return phase == Phase.TutorialWood || phase == Phase.TutorialDeliver\n            || phase == Phase.TutorialFlashlight || phase == Phase.TutorialCold\n            || phase == Phase.TutorialCoyote || phase == Phase.Level1\n            || phase == Phase.Level2IntroCoyote || phase == Phase.Level2\n            || phase == Phase.Level3 || phase == Phase.Level4;\n    }\n\n    void SkipCurrentLevel()\n    {\n        switch (phase)\n        {\n            case Phase.TutorialWood:\n            case Phase.TutorialDeliver:\n            case Phase.TutorialFlashlight:\n            case Phase.TutorialCold:\n            case Phase.TutorialCoyote:\n                ClearGameplayObjects();\n                BeginLevel1();\n                break;\n            case Phase.Level1:\n                BeginLevelTwoIntro();\n                break;\n            case Phase.Level2IntroCoyote:\n                ClearGameplayObjects();\n                StartCoroutine(FinishLevelTwoIntro());\n                break;\n            case Phase.Level2:\n                coyotesKilled = coyotesToKillForJacket;\n                StartCoroutine(LevelThreeTransitionSequence());\n                break;\n            case Phase.Level3:\n                StartCoroutine(BeginLevelFourSequence());\n                break;\n            case Phase.Level4:\n                StartCoroutine(GodCaptureSequence());\n                break;\n        }\n    }\n\n    void OnDestroy()\n    {\n        IsPlaying = false;\n        Time.timeScale = 1f;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n    }\n\n\n    // Campaign expansion and culture-board implementation.\n    [Header(\"Level 2 — Coyote Hunt\")]\n    [Min(1)] public int coyotesToKillForJacket = 10;\n    [Tooltip(\"Level 2 delay after the scripted first Coyote. Lower values speed up the hunt.\")]\n    [Min(1f)] public float levelTwoCoyoteMinDelay = 5f;\n    [Min(1f)] public float levelTwoCoyoteMaxDelay = 8f;\n    [Min(0f)] public float levelTwoCoyoteCooldown = 1f;\n    [Min(1f)] public float levelTwoCoyoteWarningSeconds = 4.5f;\n    [Min(1f)] public float gunShotRange = 80f;\n    [Min(.05f)] public float gunShotCooldown = .7f;\n    [Min(.1f)] public float gunBodyHitRadius = .48f;\n    public GameObject handgunPrefab;\n    public AudioClip gunshotSound;\n    public AudioClip chantAudio;\n\n    [Header(\"Level 3 — Exploration\")]\n    [Min(30f)] public float levelThreeDeadlineSeconds = 420f;\n    [Min(1f)] public float levelThreeCoyoteDelayMultiplier = 4f;\n    [Range(0f, 1f)] public float jacketColdDrainMultiplier = .12f;\n    [Tooltip(\"Edit the three campaign notes here. Each note reveals part of the island story.\")]\n    public string[] levelThreeNoteTexts =\n    {\n        \"The god #@*(@) needs sacrifices to survive. Usually human children.\",\n        \"The god (#@*!_- whisks people from different dimensions into this world. If you are here, there is no way to go back.\",\n        \"The god *(9!)(*@# is coming. Do your best to run away!\"\n    };\n    [Tooltip(\"Normalized terrain position (x,z) for the abandoned campsite.\")]\n    public Vector2 cultureCampMapPosition = new Vector2(.48f, .50f);\n    [Tooltip(\"Normalized terrain position (x,z) for the western temple ruins.\")]\n    public Vector2 cultureTempleMapPosition = new Vector2(.22f, .67f);\n    [Tooltip(\"Normalized terrain position (x,z) for the grove of trees with eyes.\")]\n    public Vector2 cultureEyeGroveMapPosition = new Vector2(.76f, .72f);\n    [Tooltip(\"Normalized terrain position (x,z) for the abandoned shelter.\")]\n    public Vector2 cultureShelterMapPosition = new Vector2(.68f, .27f);\n\n    [Header(\"Level 4 — God Chase\")]\n    [Tooltip(\"Player movement speed during the final chase, in world units per second.\")]\n    [Min(0f)] public float levelFourPlayerSpeed = 30f;\n    [Min(5f)] public float levelFourCoyoteMinDelay = 14f;\n    [Min(5f)] public float levelFourCoyoteMaxDelay = 22f;\n    [Min(0f)] public float levelFourCoyoteCooldown = 2f;\n    [Min(1f)] public float levelFourCoyoteWarningSeconds = 3f;\n    [Min(3f)] public float levelFourCoyoteSpawnMinDistance = 8f;\n    [Min(4f)] public float levelFourCoyoteSpawnMaxDistance = 16f;\n    [Min(0f)] public float levelFourCoyoteLateralRange = 2f;\n    [Tooltip(\"Boss height is this many times the player's actual controller height.\")]\n    [Min(2f)] public float godHeightInPlayerHeights = 22f;\n    [Min(2f)] public float godMaxHeightInPlayerHeights = 38f;\n    [Min(0f)] public float godGrowthPlayerHeightsPerSecond = .2f;\n    [Min(1f)] public float godChaseSpeed = 3.4f;\n    [Min(10f)] public float godStartDistance = 55f;\n    [Min(0f)] public float godCatchGraceSeconds = 60f;\n    [Min(1f)] public float godGrabDistance = 5f;\n    [Min(5f)] public float godExitInset = 14f;\n    [Min(.1f)] public float godFinalFadeSeconds = 2.5f;\n    [Min(0f)] public float godChantVolume = .45f;\n    [Tooltip(\"Existing scare audio used as the player's death cry when the God bites.\")]\n    public AudioClip playerDeathSound;\n    [Range(0f, 1f)] public float playerDeathSoundVolume = 1f;\n\n    readonly List<Image> campaignNoteMapDots = new List<Image>();\n    readonly Dictionary<Color, Material> cultureMaterials = new Dictionary<Color, Material>();\n    readonly HashSet<int> foundCampaignNoteIndices = new HashSet<int>();\n    GameObject campaignMapPanel;\n    RectTransform campaignMapArea;\n    Image campaignPlayerDot;\n    Text campaignMapInstructions;\n    Text godOmenText;\n    Text campaignCrosshair;\n    Text mapHintText;\n    readonly List<Image> cultureMapDots = new List<Image>();\n    readonly List<Text> cultureMapLabels = new List<Text>();\n    GameObject gunModel;\n    Transform godRoot;\n    Transform godHead;\n    Transform godHand;\n    Transform escapeBeacon;\n    AudioSource godChantSource;\n    AudioClip campaignChant;\n    Vector3 cultureCampPosition;\n    Vector3 cultureTemplePosition;\n    Vector3 cultureEyeGrovePosition;\n    Vector3 cultureShelterPosition;\n    Vector3[] campaignNotePositions;\n    Vector3 godExitPosition;\n    Vector3 godDirectionToExit;\n    Vector3 levelFourStartPosition;\n    Quaternion levelFourStartRotation;\n    float levelThreeDeadlineRemaining;\n    float nextGodOmenTime;\n    float nextGunShotTime;\n    float godChaseStartTime;\n    float nextGraceHudUpdate;\n    float currentGodHeightInPlayerHeights;\n    int levelThreeNotesFound;\n    int coyotesKilled;\n    bool gunUnlocked;\n    bool mapOpen;\n    bool movementWasEnabledBeforeMap;\n    bool advanceToLevelFour;\n    bool godSequenceRunning;\n    bool godEdgeSequenceRunning;\n    Color originalAmbientColor;\n    float originalAmbientIntensity;\n    float originalReflectionIntensity;\n    float originalDirectionalIntensity;\n    float originalCameraFarClip;\n    bool originalFog;\n    FogMode originalFogMode;\n    float originalFogDensity;\n    Color originalFogColor;\n    Vector3 savedPlayerPosition;\n\n    void CacheCultureLighting()\n    {\n        originalAmbientColor = RenderSettings.ambientLight;\n        originalAmbientIntensity = RenderSettings.ambientIntensity;\n        originalReflectionIntensity = RenderSettings.reflectionIntensity;\n        originalFog = RenderSettings.fog;\n        originalFogMode = RenderSettings.fogMode;\n        originalFogDensity = RenderSettings.fogDensity;\n        originalFogColor = RenderSettings.fogColor;\n        originalDirectionalIntensity = directionalLight != null ? directionalLight.intensity : .8f;\n        originalCameraFarClip = gameplayCamera != null ? gameplayCamera.farClipPlane : 1000f;\n    }\n\n    void BuildCampaignUI()\n    {\n        campaignMapPanel = NewPanel(canvas.transform, \"Level 3 Field Map\", new Vector2(.15f, .09f), new Vector2(.85f, .91f), new Color(.025f, .04f, .035f, .97f));\n        Text title = NewText(campaignMapPanel.transform, \"Map Title\", \"FIELD MAP  |  DARAEL\", 30, new Vector2(.05f, .91f), new Vector2(.95f, .99f));\n        title.alignment = TextAnchor.MiddleCenter;\n        campaignMapArea = (RectTransform)NewImage(campaignMapPanel.transform, \"Map Area\", new Vector2(.08f, .13f), new Vector2(.92f, .88f)).rectTransform;\n        Image mapAreaImage = campaignMapArea.GetComponent<Image>();\n        mapAreaImage.color = new Color(.13f, .17f, .13f, 1f);\n        AddMapGridLine(campaignMapArea, new Vector2(.5f, 0f), new Vector2(.5f, 1f), new Color(.32f, .35f, .28f, .6f));\n        AddMapGridLine(campaignMapArea, new Vector2(0f, .5f), new Vector2(1f, .5f), new Color(.32f, .35f, .28f, .6f));\n        Text compass = NewText(campaignMapPanel.transform, \"Compass\", \"N\\n▲\", 22, new Vector2(.86f, .79f), new Vector2(.95f, .9f));\n        compass.alignment = TextAnchor.MiddleCenter;\n        campaignMapInstructions = NewText(campaignMapPanel.transform, \"Map Instructions\", \"F — CLOSE MAP    |    AMBER DOTS — UNREAD NOTES    |    R — READ NEAR NOTE\", 18, new Vector2(.03f, .025f), new Vector2(.97f, .105f));\n        campaignMapInstructions.alignment = TextAnchor.MiddleCenter;\n        CreateCultureMapSite(\"Camp\", new Color(.84f, .72f, .48f));\n        CreateCultureMapSite(\"Temple\", new Color(.76f, .47f, .32f));\n        CreateCultureMapSite(\"Eyes\", new Color(.6f, .78f, .52f));\n        CreateCultureMapSite(\"Shelter\", new Color(.68f, .7f, .72f));\n        campaignPlayerDot = CreateMapDot(\"Player Location\", Color.cyan, 20f);\n        campaignPlayerDot.transform.SetParent(campaignMapArea, false);\n        campaignPlayerDot.gameObject.name = \"Player Map Marker\";\n        for (int i = 0; i < 3; i++)\n        {\n            Image dot = CreateMapDot(\"Unfound Note \" + (i + 1), new Color(1f, .78f, .25f), 18f);\n            dot.transform.SetParent(campaignMapArea, false);\n            campaignNoteMapDots.Add(dot);\n        }\n        campaignMapPanel.SetActive(false);\n\n        godOmenText = NewText(canvas.transform, \"God Omen\", \"GOD IS COMING\", 46, new Vector2(.2f, .72f), new Vector2(.8f, .86f));\n        godOmenText.alignment = TextAnchor.MiddleCenter;\n        godOmenText.fontStyle = FontStyle.Bold;\n        godOmenText.color = new Color(1f, .04f, .025f, 0f);\n        godOmenText.gameObject.SetActive(false);\n        campaignCrosshair = NewText(canvas.transform, \"Gun Crosshair\", \"+\", 28, new Vector2(.485f, .485f), new Vector2(.515f, .535f));\n        campaignCrosshair.alignment = TextAnchor.MiddleCenter;\n        campaignCrosshair.gameObject.SetActive(false);\n    }\n\n    void CreateCultureMapSite(string name, Color color)\n    {\n        Image dot = CreateMapDot(name + \" Landmark\", color, 13f);\n        dot.transform.SetParent(campaignMapArea, false);\n        cultureMapDots.Add(dot);\n        Text label = NewText(campaignMapArea, name + \" Label\", name, 14, Vector2.zero, Vector2.zero);\n        label.rectTransform.sizeDelta = new Vector2(110f, 22f);\n        label.alignment = TextAnchor.MiddleLeft;\n        label.color = Color.white;\n        cultureMapLabels.Add(label);\n    }\n\n    Image CreateMapDot(string name, Color color, float size)\n    {\n        GameObject dotObject = new GameObject(name, typeof(RectTransform));\n        dotObject.transform.SetParent(campaignMapArea, false);\n        Image dot = dotObject.AddComponent<Image>();\n        dot.color = color;\n        RectTransform rect = dot.rectTransform;\n        rect.anchorMin = Vector2.zero;\n        rect.anchorMax = Vector2.zero;\n        rect.sizeDelta = new Vector2(size, size);\n        rect.anchoredPosition = Vector2.zero;\n        return dot;\n    }\n\n    void AddMapGridLine(Transform parent, Vector2 start, Vector2 end, Color color)\n    {\n        GameObject line = new GameObject(\"Map Grid Line\", typeof(RectTransform));\n        line.transform.SetParent(parent, false);\n        Image image = line.AddComponent<Image>();\n        image.color = color;\n        RectTransform rect = image.rectTransform;\n        Vector2 delta = end - start;\n        rect.anchorMin = start;\n        rect.anchorMax = start;\n        rect.pivot = new Vector2(.5f, .5f);\n        rect.sizeDelta = new Vector2(delta.magnitude * 800f, 2f);\n        rect.anchoredPosition = delta * 400f;\n        rect.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(delta.y, delta.x) * Mathf.Rad2Deg);\n    }\n\n    void CreateCultureBoardWorld()\n    {\n        if (terrain == null || terrain.terrainData == null) return;\n        cultureCampPosition = FindClearTerrainPoint(TerrainPoint(cultureCampMapPosition), 10f);\n        cultureTemplePosition = FindClearTerrainPoint(TerrainPoint(cultureTempleMapPosition), 18f);\n        cultureEyeGrovePosition = FindClearTerrainPoint(TerrainPoint(cultureEyeGroveMapPosition), 13f);\n        cultureShelterPosition = FindClearTerrainPoint(TerrainPoint(cultureShelterMapPosition), 12f);\n        CreateAbandonedCampsite(cultureCampPosition);\n        CreateWesternTemple(cultureTemplePosition);\n        CreateEyeTreeGrove(cultureEyeGrovePosition);\n        CreateAbandonedShelter(cultureShelterPosition);\n        CreateCampingSymbolTrail(cultureCampPosition, cultureTemplePosition);\n\n        Physics.SyncTransforms();\n        campaignNotePositions = new Vector3[3];\n        campaignNotePositions[0] = FindAccessibleNotePoint(cultureTemplePosition + new Vector3(10f, 0f, 6f), 18f);\n        campaignNotePositions[1] = FindAccessibleNotePoint(cultureEyeGrovePosition + new Vector3(-8f, 0f, 5f), 18f);\n        campaignNotePositions[2] = FindAccessibleNotePoint(cultureShelterPosition + new Vector3(7f, 0f, -6f), 18f);\n    }\n\n    Vector3 TerrainPoint(Vector2 normalized)\n    {\n        Vector3 origin = terrain.transform.position;\n        Vector3 size = terrain.terrainData.size;\n        Vector3 point = new Vector3(origin.x + size.x * Mathf.Clamp01(normalized.x), 0f, origin.z + size.z * Mathf.Clamp01(normalized.y));\n        point.y = terrain.SampleHeight(point) + origin.y;\n        return point;\n    }\n\n    Vector3 FindClearTerrainPoint(Vector3 desired, float radius)\n    {\n        if (terrain == null || terrain.terrainData == null) return desired;\n        Vector3 best = desired;\n        float bestClearance = -1f;\n        TreeInstance[] trees = terrain.terrainData.treeInstances;\n        const int samples = 9;\n        for (int x = -samples; x <= samples; x++)\n        {\n            for (int z = -samples; z <= samples; z++)\n            {\n                Vector3 candidate = desired + new Vector3(x * radius / samples, 0f, z * radius / samples);\n                candidate = ClampToTerrain(candidate);\n                float nearestTree = float.MaxValue;\n                for (int i = 0; i < trees.Length; i++)\n                {\n                    Vector3 treePoint = terrain.transform.position + Vector3.Scale(trees[i].position, terrain.terrainData.size);\n                    float distance = (new Vector2(treePoint.x - candidate.x, treePoint.z - candidate.z)).magnitude;\n                    if (distance < nearestTree) nearestTree = distance;\n                }\n                if (nearestTree > bestClearance)\n                {\n                    bestClearance = nearestTree;\n                    best = candidate;\n                }\n            }\n        }\n        return best;\n    }\n\n    Vector3 FindAccessibleNotePoint(Vector3 desired, float searchRadius)\n    {\n        if (terrain == null || terrain.terrainData == null) return desired;\n        Vector3 best = ClampToTerrain(desired);\n        float bestDistance = float.MaxValue;\n        const float spacing = 1.5f;\n        int steps = Mathf.CeilToInt(searchRadius / spacing);\n        for (int x = -steps; x <= steps; x++)\n        for (int z = -steps; z <= steps; z++)\n        {\n            Vector3 candidate = ClampToTerrain(desired + new Vector3(x * spacing, 0f, z * spacing));\n            if (HasBlockingNoteAccess(candidate)) continue;\n            float distance = (candidate - desired).sqrMagnitude;\n            if (distance < bestDistance)\n            {\n                best = candidate;\n                bestDistance = distance;\n            }\n        }\n        if (bestDistance == float.MaxValue)\n        {\n            Debug.LogWarning(\"No clear note spot was found near a Level 3 landmark; placing it at the closest terrain point.\");\n            return FindClearTerrainPoint(desired, searchRadius);\n        }\n        return best;\n    }\n\n    bool HasBlockingNoteAccess(Vector3 groundPoint)\n    {\n        Vector3 foot = groundPoint + Vector3.up * .38f;\n        Vector3 head = groundPoint + Vector3.up * 1.55f;\n        Collider[] blockers = Physics.OverlapCapsule(foot, head, .32f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);\n        foreach (Collider blocker in blockers)\n        {\n            if (blocker == null || blocker.isTrigger) continue;\n            if (blocker.GetComponent<TerrainCollider>() != null) continue;\n            if (player != null && (blocker.transform == player || blocker.transform.IsChildOf(player))) continue;\n            return true;\n        }\n        return false;\n    }\n\n    Material CultureMaterial(Color color, bool emissive = false)\n    {\n        if (!emissive && cultureMaterials.TryGetValue(color, out Material cached)) return cached;\n        Shader shader = Shader.Find(\"Universal Render Pipeline/Lit\") ?? Shader.Find(\"Standard\");\n        if (shader == null) return null;\n        Material material = new Material(shader);\n        material.color = color;\n        if (emissive)\n        {\n            material.EnableKeyword(\"_EMISSION\");\n            material.SetColor(\"_EmissionColor\", color * 1.6f);\n        }\n        else cultureMaterials[color] = material;\n        return material;\n    }\n\n    GameObject CulturePrimitive(Transform parent, PrimitiveType type, string name, Vector3 position, Vector3 scale, Color color, bool emissive = false, Quaternion? rotation = null)\n    {\n        GameObject item = GameObject.CreatePrimitive(type);\n        item.name = name;\n        item.transform.SetParent(parent, true);\n        item.transform.position = position;\n        item.transform.localScale = scale;\n        if (rotation.HasValue) item.transform.rotation = rotation.Value;\n        Collider collider = item.GetComponent<Collider>();\n        if (collider != null) Destroy(collider);\n        Renderer renderer = item.GetComponent<Renderer>();\n        Material material = CultureMaterial(color, emissive);\n        if (renderer != null && material != null)\n        {\n            renderer.sharedMaterial = material;\n            renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.On;\n        }\n        return item;\n    }\n\n    void CreateAbandonedCampsite(Vector3 center)\n    {\n        GameObject camp = new GameObject(\"Abandoned Campsite — Cultural Layer\");\n        camp.transform.position = center;\n        Color bark = new Color(.16f, .095f, .055f);\n        Color canvas = new Color(.22f, .25f, .20f);\n        for (int i = 0; i < 3; i++)\n        {\n            CulturePrimitive(camp.transform, PrimitiveType.Cylinder, \"Discarded firewood\", center + new Vector3(-1.3f + i * .2f, .18f, -1.2f), new Vector3(.12f, .9f, .12f), bark, false, Quaternion.Euler(0f, 0f, 90f));\n        }\n        CulturePrimitive(camp.transform, PrimitiveType.Cube, \"Collapsed canvas shelter\", center + new Vector3(0f, 1.15f, 1.5f), new Vector3(3f, .12f, 2.4f), canvas, false, Quaternion.Euler(22f, 0f, 0f));\n        CulturePrimitive(camp.transform, PrimitiveType.Cylinder, \"Cold fire ring\", center + new Vector3(0f, .12f, -.1f), new Vector3(1.3f, .18f, 1.3f), new Color(.12f, .13f, .12f));\n        CulturePrimitive(camp.transform, PrimitiveType.Cube, \"Abandoned field journal\", center + new Vector3(.8f, .38f, .15f), new Vector3(.4f, .06f, .3f), new Color(.55f, .43f, .26f));\n        AddCultureLight(camp.transform, center + new Vector3(0f, .4f, -.1f), new Color(1f, .33f, .08f), 2.2f, 7f);\n        AddRuneMarker(camp.transform, center + new Vector3(-1.2f, .22f, 1.2f), new Color(.7f, .08f, .055f));\n    }\n\n    void CreateAbandonedShelter(Vector3 center)\n    {\n        GameObject shelter = new GameObject(\"Abandoned Shelter — Cultural Layer\");\n        shelter.transform.position = center;\n        Color wood = new Color(.11f, .085f, .065f);\n        Color tarp = new Color(.08f, .12f, .105f);\n        CulturePrimitive(shelter.transform, PrimitiveType.Cube, \"Broken shelter wall\", center + new Vector3(0f, 1f, 0f), new Vector3(3.2f, 2f, .18f), wood);\n        CulturePrimitive(shelter.transform, PrimitiveType.Cube, \"Torn roof\", center + new Vector3(0f, 2.1f, -.35f), new Vector3(3.5f, .1f, 2.1f), tarp, false, Quaternion.Euler(0f, 0f, -9f));\n        CulturePrimitive(shelter.transform, PrimitiveType.Cube, \"Collapsed doorway\", center + new Vector3(1.15f, .6f, .14f), new Vector3(.12f, 1.2f, .25f), new Color(.04f, .035f, .03f));\n        AddRuneMarker(shelter.transform, center + new Vector3(-.6f, 1.1f, .12f), new Color(.7f, .08f, .055f));\n    }\n\n    void CreateWesternTemple(Vector3 center)\n    {\n        GameObject temple = new GameObject(\"Western Strange Temple — Cultural Layer\");\n        temple.transform.position = center;\n        Color stone = new Color(.17f, .19f, .17f);\n        Color rune = new Color(.34f, .045f, .035f);\n        float[] xs = { -3f, -1f, 1f, 3f };\n        for (int i = 0; i < xs.Length; i++)\n        {\n            CulturePrimitive(temple.transform, PrimitiveType.Cube, \"Standing temple pillar\", center + new Vector3(xs[i], 2.4f, 0f), new Vector3(.55f, 4.8f, .65f), stone);\n            CulturePrimitive(temple.transform, PrimitiveType.Cube, \"Carved red sigil\", center + new Vector3(xs[i], 2.5f, .34f), new Vector3(.2f, 1.25f, .025f), rune, true);\n        }\n        CulturePrimitive(temple.transform, PrimitiveType.Cube, \"Temple lintel\", center + new Vector3(0f, 4.85f, 0f), new Vector3(7.2f, .7f, .9f), stone);\n        CulturePrimitive(temple.transform, PrimitiveType.Cube, \"Fallen temple lintel\", center + new Vector3(-3.8f, .5f, 2.5f), new Vector3(4f, .55f, .7f), stone, false, Quaternion.Euler(0f, 0f, 16f));\n        AddCultureLight(temple.transform, center + new Vector3(0f, 2f, 2.4f), new Color(.64f, .15f, .085f), 1.2f, 13f);\n        AddRuneMarker(temple.transform, center + new Vector3(0f, .15f, 4f), new Color(.65f, .065f, .04f));\n    }\n\n    void CreateEyeTreeGrove(Vector3 center)\n    {\n        GameObject grove = new GameObject(\"Trees with Eyes — Cultural Layer\");\n        grove.transform.position = center;\n        Color bark = new Color(.10f, .09f, .075f);\n        Color leaves = new Color(.055f, .12f, .085f);\n        Color eye = new Color(1f, .29f, .035f);\n        Vector3[] offsets = { new Vector3(-8f, 0f, -4f), new Vector3(-3f, 0f, 4f), new Vector3(3f, 0f, -3f), new Vector3(8f, 0f, 5f), new Vector3(0f, 0f, -9f) };\n        for (int i = 0; i < offsets.Length; i++)\n        {\n            Vector3 ground = FindClearTerrainPoint(center + offsets[i], 3f);\n            float height = 5f + (i % 3) * 1.2f;\n            CulturePrimitive(grove.transform, PrimitiveType.Cylinder, \"Black pine trunk\", ground + Vector3.up * (height * .4f), new Vector3(.45f, height * .4f, .45f), bark);\n            CulturePrimitive(grove.transform, PrimitiveType.Sphere, \"Dark canopy\", ground + Vector3.up * (height * .95f), new Vector3(3f, 3.6f, 3f), leaves);\n            Vector3 eyeLine = ground + Vector3.up * 2.1f + Vector3.forward * .42f;\n            CulturePrimitive(grove.transform, PrimitiveType.Sphere, \"Watching eye left\", eyeLine + Vector3.left * .22f, new Vector3(.14f, .11f, .08f), eye, true);\n            CulturePrimitive(grove.transform, PrimitiveType.Sphere, \"Watching eye right\", eyeLine + Vector3.right * .22f, new Vector3(.14f, .11f, .08f), eye, true);\n        }\n        AddCultureLight(grove.transform, center + Vector3.up * 1.3f, new Color(.35f, .08f, .045f), .32f, 8f);\n    }\n\n    void CreateCampingSymbolTrail(Vector3 from, Vector3 to)\n    {\n        GameObject trail = new GameObject(\"Repeated Camping Symbols — Cultural Layer\");\n        Vector3 direction = (to - from).normalized;\n        for (int i = 1; i <= 5; i++)\n        {\n            Vector3 point = Vector3.Lerp(from, to, i / 6f);\n            point = FindClearTerrainPoint(point, 2f);\n            AddRuneMarker(trail.transform, point + Vector3.up * .05f, new Color(.44f, .06f, .035f));\n            Vector3 side = Vector3.Cross(Vector3.up, direction).normalized * .35f;\n            CulturePrimitive(trail.transform, PrimitiveType.Cube, \"Camping path slash\", point + Vector3.up * .08f + side, new Vector3(.08f, .02f, .7f), new Color(.35f, .24f, .14f), false, Quaternion.LookRotation(direction));\n        }\n    }\n\n    void AddRuneMarker(Transform parent, Vector3 point, Color glow)\n    {\n        GameObject rune = new GameObject(\"Old Camping Sigil\");\n        rune.transform.SetParent(parent, true);\n        rune.transform.position = point;\n        CulturePrimitive(rune.transform, PrimitiveType.Cylinder, \"Sigil stone\", point + Vector3.up * .1f, new Vector3(.7f, .16f, .7f), new Color(.12f, .12f, .105f));\n        CulturePrimitive(rune.transform, PrimitiveType.Cube, \"Sigil vertical\", point + Vector3.up * .22f, new Vector3(.055f, .035f, .48f), glow, true);\n        CulturePrimitive(rune.transform, PrimitiveType.Cube, \"Sigil crossbar\", point + Vector3.up * .23f, new Vector3(.4f, .035f, .055f), glow, true);\n    }\n\n    void AddCultureLight(Transform parent, Vector3 point, Color color, float intensity, float range)\n    {\n        GameObject lightObject = new GameObject(\"Subtle cultural landmark light\");\n        lightObject.transform.SetParent(parent, true);\n        lightObject.transform.position = point;\n        Light light = lightObject.AddComponent<Light>();\n        light.type = LightType.Point;\n        light.color = color;\n        light.intensity = intensity;\n        light.range = range;\n        light.shadows = LightShadows.None;\n    }\n\n    GameObject CampaignPrimitiveLocal(Transform parent, PrimitiveType type, string name, Vector3 localPosition, Vector3 localScale, Color color, Quaternion? localRotation = null, bool emissive = false)\n    {\n        GameObject item = GameObject.CreatePrimitive(type);\n        item.name = name;\n        item.transform.SetParent(parent, false);\n        item.transform.localPosition = localPosition;\n        item.transform.localScale = localScale;\n        if (localRotation.HasValue) item.transform.localRotation = localRotation.Value;\n        Collider collider = item.GetComponent<Collider>();\n        if (collider != null) Destroy(collider);\n        Renderer renderer = item.GetComponent<Renderer>();\n        Material material = CultureMaterial(color, emissive);\n        if (renderer != null && material != null) renderer.sharedMaterial = material;\n        return item;\n    }\n\n    void BeginLevelTwoIntro()\n    {\n        if (phase == Phase.CampaignTransition) return;\n        ClearGameplayObjects();\n        gunUnlocked = false;\n        coyotesKilled = 0;\n        gunModel = null;\n        if (campaignCrosshair != null) campaignCrosshair.gameObject.SetActive(false);\n        if (endPanel != null) Destroy(endPanel);\n        StartCoroutine(LevelTwoIntroSequence());\n    }\n\n    IEnumerator LevelTwoIntroSequence()\n    {\n        phase = Phase.CampaignTransition;\n        IsPlaying = false;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        dialoguePanel.SetActive(true);\n        string[] lines =\n        {\n            \"I think that’s enough wood to keep the helicopter burning.\",\n            \"I just need to wait until someone sees the smoke and gives help.\"\n        };\n        foreach (string line in lines)\n        {\n            dialogueText.text = line;\n            yield return new WaitForSeconds(3.2f);\n        }\n        phase = Phase.Level2IntroCoyote;\n        IsPlaying = true;\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        dialogueText.text = \"\";\n        dialoguePanel.SetActive(false);\n        hintText.text = \"A Coyote! Flash your light until it runs away.\";\n        SpawnCoyote(true);\n        UpdateHud();\n    }\n\n    IEnumerator FinishLevelTwoIntro()\n    {\n        if (phase != Phase.Level2IntroCoyote) yield break;\n        phase = Phase.CampaignTransition;\n        IsPlaying = false;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        dialoguePanel.SetActive(true);\n        string[] lines =\n        {\n            \"These Coyotes keep coming back. I need a way to fight them.\",\n            \"Wait… I think my dad gave me a gun.\",\n            \"Now I can fight back. Maybe I can use their fur to make a warm jacket.\"\n        };\n        foreach (string line in lines)\n        {\n            dialogueText.text = line;\n            yield return new WaitForSeconds(3.4f);\n        }\n        gunUnlocked = true;\n        SetGunVisible(true);\n        phase = Phase.Level2;\n        levelCoyoteTimer = GetNextCoyoteSpawnDelay();\n        campaignMatchSpawnTimer = GetCampaignMatchSpawnDelay(phase);\n        dialogueText.text = \"\";\n        dialoguePanel.SetActive(false);\n        hintText.text = \"Press T to fire. A body hit kills; a miss scares the Coyote away.\";\n        IsPlaying = true;\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        UpdateHud();\n    }\n\n    void CreateOrShowGun()\n    {\n        if (gunModel == null && playerCamera != null)\n        {\n            if (handgunPrefab == null)\n                handgunPrefab = Resources.Load<GameObject>(\"M1911 Handgun_Black\");\n            if (handgunPrefab != null)\n            {\n                gunModel = Instantiate(handgunPrefab, playerCamera);\n                gunModel.name = \"Dad’s Handgun — First Person Model\";\n                gunModel.transform.localPosition = new Vector3(.34f, -.32f, .65f);\n                gunModel.transform.localRotation = Quaternion.identity;\n                gunModel.transform.localScale = Vector3.one * .6f;\n            }\n            else\n            {\n                gunModel = new GameObject(\"Generated Handgun Stand-In\");\n                gunModel.transform.SetParent(playerCamera, false);\n                gunModel.transform.localPosition = new Vector3(.34f, -.31f, .6f);\n                CampaignPrimitiveLocal(gunModel.transform, PrimitiveType.Cube, \"Gun slide\", Vector3.zero, new Vector3(.18f, .12f, .42f), new Color(.12f, .13f, .14f));\n            }\n        }\n        SetGunVisible(gunUnlocked);\n    }\n\n    void SetGunVisible(bool visible)\n    {\n        if (gunModel == null) CreateOrShowGun();\n        if (gunModel != null) gunModel.SetActive(visible);\n        if (campaignCrosshair != null) campaignCrosshair.gameObject.SetActive(visible);\n    }\n\n    void TryFireGun()\n    {\n        if (!gunUnlocked || (phase != Phase.Level2 && phase != Phase.Level3)) return;\n        if (Time.time < nextGunShotTime) return;\n        nextGunShotTime = Time.time + gunShotCooldown;\n        if (gunshotSound != null && audioSource != null) audioSource.PlayOneShot(gunshotSound, 1f);\n        if (playerCamera == null) return;\n        Vector3 muzzle = playerCamera.position + playerCamera.forward * .62f + playerCamera.right * .32f - playerCamera.up * .28f;\n        Transform targetCoyote = activeCoyote != null && !coyoteEscaping ? activeCoyote : null;\n        StartCoroutine(GunProjectileRoutine(muzzle, playerCamera.forward, targetCoyote));\n    }\n\n    IEnumerator GunProjectileRoutine(Vector3 muzzle, Vector3 direction, Transform targetCoyote)\n    {\n        Shader shader = Shader.Find(\"Universal Render Pipeline/Lit\") ?? Shader.Find(\"Standard\");\n        Material tracerMaterial = CreateMaterial(shader, new Color(1f, .48f, .08f), true);\n        GameObject bullet = GameObject.CreatePrimitive(PrimitiveType.Sphere);\n        bullet.name = \"Gunshot Bullet Tracer\";\n        bullet.transform.position = muzzle;\n        bullet.transform.localScale = Vector3.one * .075f;\n        Collider bulletCollider = bullet.GetComponent<Collider>();\n        if (bulletCollider != null) Destroy(bulletCollider);\n        Renderer bulletRenderer = bullet.GetComponent<Renderer>();\n        if (bulletRenderer != null && tracerMaterial != null) bulletRenderer.sharedMaterial = tracerMaterial;\n\n        GameObject trailObject = new GameObject(\"Gunshot Trail\");\n        LineRenderer trail = trailObject.AddComponent<LineRenderer>();\n        trail.useWorldSpace = true;\n        trail.positionCount = 2;\n        trail.startWidth = .035f;\n        trail.endWidth = .008f;\n        trail.numCapVertices = 2;\n        trail.material = tracerMaterial;\n        trail.startColor = new Color(1f, .84f, .35f, .95f);\n        trail.endColor = new Color(1f, .18f, .025f, .1f);\n        trail.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;\n        Vector3 position = muzzle;\n        float distanceTravelled = 0f;\n        bool hitCoyote = false;\n        const float bulletSpeed = 220f;\n\n        while (distanceTravelled < gunShotRange)\n        {\n            float step = Mathf.Min(bulletSpeed * Time.deltaTime, gunShotRange - distanceTravelled);\n            Vector3 next = position + direction * step;\n            if (Physics.Raycast(position, direction, out RaycastHit hit, step, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore))\n            {\n                next = hit.point;\n                hitCoyote = targetCoyote != null && (hit.transform == targetCoyote || hit.transform.IsChildOf(targetCoyote));\n                position = next;\n                bullet.transform.position = position;\n                trail.SetPosition(0, position - direction * .8f);\n                trail.SetPosition(1, position);\n                break;\n            }\n\n            if (targetCoyote != null && activeCoyote == targetCoyote)\n            {\n                Vector3 targetPoint = targetCoyote.position + Vector3.up * .75f;\n                Vector3 segment = next - position;\n                float along = Mathf.Clamp(Vector3.Dot(targetPoint - position, direction), 0f, step);\n                Vector3 nearest = position + direction * along;\n                if (Vector3.Distance(nearest, targetPoint) <= gunBodyHitRadius)\n                {\n                    hitCoyote = true;\n                    next = nearest;\n                }\n            }\n\n            position = next;\n            distanceTravelled += step;\n            bullet.transform.position = position;\n            trail.SetPosition(0, position - direction * .8f);\n            trail.SetPosition(1, position);\n            if (hitCoyote) break;\n            yield return null;\n        }\n\n        if (hitCoyote && targetCoyote != null && activeCoyote == targetCoyote)\n        {\n            KillActiveCoyote();\n            hintText.text = \"Direct hit. Coyote fur collected.\";\n        }\n        else if (targetCoyote != null && activeCoyote == targetCoyote)\n        {\n            ScareCoyoteAway();\n            hintText.text = \"The shot missed. The gunshot scared it away.\";\n        }\n\n        Destroy(bullet);\n        Destroy(trailObject);\n        if (tracerMaterial != null) Destroy(tracerMaterial);\n    }\n\n    void KillActiveCoyote()\n    {\n        if (activeCoyote == null) return;\n        StopCoyoteSound();\n        Destroy(activeCoyote.gameObject);\n        activeCoyote = null;\n        coyoteChasing = false;\n        coyoteEscaping = false;\n        coyotesKilled++;\n        hintText.text = \"Coyote fur collected.\";\n        if (phase == Phase.Level2 && coyotesKilled >= coyotesToKillForJacket)\n        {\n            StartCoroutine(LevelThreeTransitionSequence());\n            return;\n        }\n        levelCoyoteTimer = GetNextCoyoteSpawnDelay();\n        UpdateHud();\n    }\n\n    IEnumerator LevelThreeTransitionSequence()\n    {\n        phase = Phase.CampaignTransition;\n        IsPlaying = false;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        dialoguePanel.SetActive(true);\n        dialogueText.text = \"Ten Coyotes… that should be enough fur for a warm jacket.\";\n        yield return new WaitForSeconds(3f);\n        dialogueText.text = \"Maybe I should explore this place. No helicopter has come. I can see the Earth from here…\";\n        yield return new WaitForSeconds(3.5f);\n        BeginLevelThree();\n    }\n\n    void BeginLevelThree()\n    {\n        ClearGameplayObjects();\n        player.position = levelOneCheckpoint;\n        player.rotation = levelOneCheckpointRotation;\n        if (playerCamera != null)\n        {\n            playerCamera.SetParent(player, false);\n            playerCamera.localPosition = new Vector3(0f, 1.5f, 0f);\n            playerCamera.localRotation = Quaternion.identity;\n            cameraBaseLocalPosition = playerCamera.localPosition;\n        }\n        if (movement != null) movement.ResetView();\n        gunUnlocked = true;\n        CreateOrShowGun();\n        hypothermia = startingHypothermia;\n        coldWarningShown = false;\n        levelThreeNotesFound = foundCampaignNoteIndices.Count;\n        levelThreeDeadlineRemaining = levelThreeDeadlineSeconds;\n        campaignMatchSpawnTimer = GetCampaignMatchSpawnDelay(Phase.Level3);\n        phase = Phase.Level3;\n        IsPlaying = true;\n        dialogueText.text = \"Maybe I can find a way home. I should look for the three marked notes.\";\n        dialoguePanel.SetActive(true);\n        SpawnLevelThreeNotes();\n        levelCoyoteTimer = GetNextCoyoteSpawnDelay();\n        if (campaignMapPanel != null) campaignMapPanel.SetActive(false);\n        mapOpen = false;\n        StartCoroutine(LevelThreeDeadlineRoutine());\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        ApplyLevelOneDarkness();\n        UpdateHud();\n        StartCoroutine(HideLevelThreeIntroDialogue());\n    }\n\n    IEnumerator HideLevelThreeIntroDialogue()\n    {\n        yield return new WaitForSeconds(4f);\n        if (phase == Phase.Level3 && dialoguePanel != null) dialoguePanel.SetActive(false);\n    }\n\n    IEnumerator LevelThreeDeadlineRoutine()\n    {\n        float remaining = Mathf.Max(1f, levelThreeDeadlineSeconds);\n        while (remaining > 0f && phase == Phase.Level3)\n        {\n            yield return null;\n            remaining -= Time.deltaTime;\n            levelThreeDeadlineRemaining = Mathf.Max(0f, remaining);\n            if (Time.frameCount % 10 == 0) UpdateHud();\n        }\n        if (phase == Phase.Level3) StartCoroutine(BeginLevelFourSequence());\n    }\n\n    void SpawnLevelThreeNotes()\n    {\n        if (campaignNotePositions == null) return;\n        for (int i = 0; i < campaignNotePositions.Length; i++)\n        {\n            if (foundCampaignNoteIndices.Contains(i)) continue;\n            string noteText = levelThreeNoteTexts != null && i < levelThreeNoteTexts.Length\n                ? levelThreeNoteTexts[i]\n                : \"The ink has faded. This note may once have explained the island.\";\n            SpawnWorldNote(campaignNotePositions[i], noteText);\n            WorldNotePickup pickup = notePickups[notePickups.Count - 1];\n            pickup.campaignNote = true;\n            pickup.campaignIndex = i;\n        }\n        UpdateMapMarkers();\n    }\n\n    void RegisterCampaignNoteFound(int index)\n    {\n        if (foundCampaignNoteIndices.Add(index)) levelThreeNotesFound = foundCampaignNoteIndices.Count;\n        UpdateMapMarkers();\n        UpdateHud();\n        if (levelThreeNotesFound >= 3) advanceToLevelFour = true;\n    }\n\n    bool AdvanceToLevelFourAfterNoteCloses()\n    {\n        if (!advanceToLevelFour) return false;\n        advanceToLevelFour = false;\n        return true;\n    }\n\n    IEnumerator BeginLevelFourSequence()\n    {\n        if (phase == Phase.Level4 || phase == Phase.FinalEnding) yield break;\n        ClearGameplayObjects();\n        phase = Phase.CampaignTransition;\n        IsPlaying = false;\n        mapOpen = false;\n        if (campaignMapPanel != null) campaignMapPanel.SetActive(false);\n        if (movement != null && movementWasEnabledBeforeMap) movement.enabled = true;\n        if (notePanel != null) notePanel.SetActive(false);\n        noteOpen = false;\n        if (movement != null && movementWasEnabledBeforeNote) movement.enabled = true;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        dialoguePanel.SetActive(true);\n        dialogueText.text = \"The chanting is coming from the edge of the forest. Run!\";\n        yield return new WaitForSeconds(3f);\n        dialoguePanel.SetActive(false);\n        BeginLevelFour();\n    }\n\n    void BeginLevelFour()\n    {\n        phase = Phase.Level4;\n        IsPlaying = true;\n        levelFourStartPosition = player.position;\n        levelFourStartRotation = player.rotation;\n        if (movement != null) movement.SetMoveSpeed(levelFourPlayerSpeed);\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        RenderSettings.fog = false;\n        RenderSettings.ambientLight = Color.gray;\n        RenderSettings.ambientIntensity = Mathf.Max(.35f, originalAmbientIntensity);\n        RenderSettings.reflectionIntensity = Mathf.Max(.5f, originalReflectionIntensity);\n        if (directionalLight != null) directionalLight.intensity = Mathf.Max(.65f, originalDirectionalIntensity);\n        if (gameplayCamera != null) gameplayCamera.farClipPlane = Mathf.Max(600f, originalCameraFarClip);\n        CreateOrShowGun();\n        godExitPosition = FindFarthestMapEdge(player.position);\n        godDirectionToExit = godExitPosition - player.position;\n        godDirectionToExit.y = 0f;\n        if (godDirectionToExit.sqrMagnitude < .01f) godDirectionToExit = player.forward;\n        godDirectionToExit.Normalize();\n        player.rotation = Quaternion.LookRotation(godDirectionToExit, Vector3.up);\n        if (playerCamera != null) playerCamera.rotation = Quaternion.LookRotation(godDirectionToExit + Vector3.up * -.05f, Vector3.up);\n        BuildExitBeacon(godExitPosition);\n        godChaseStartTime = Time.time;\n        currentGodHeightInPlayerHeights = godHeightInPlayerHeights;\n        nextGraceHudUpdate = Time.time + 1f;\n        CreateGod(player.position - godDirectionToExit * godStartDistance);\n        SpawnCoyote(false);\n        nextGodOmenTime = Time.time + 4f;\n        if (godOmenText != null) godOmenText.gameObject.SetActive(true);\n        PlayGodChant();\n        hintText.text = \"A Coyote blocks the trail! Flash or shoot it, then run for the red light.\";\n        UpdateHud();\n    }\n\n    Vector3 FindFarthestMapEdge(Vector3 from)\n    {\n        if (terrain == null || terrain.terrainData == null) return from + player.forward * 250f;\n        Vector3 origin = terrain.transform.position;\n        Vector3 size = terrain.terrainData.size;\n        float inset = Mathf.Clamp(godExitInset, 5f, Mathf.Min(size.x, size.z) * .2f);\n        Vector3[] corners =\n        {\n            new Vector3(origin.x + inset, 0f, origin.z + inset),\n            new Vector3(origin.x + size.x - inset, 0f, origin.z + inset),\n            new Vector3(origin.x + inset, 0f, origin.z + size.z - inset),\n            new Vector3(origin.x + size.x - inset, 0f, origin.z + size.z - inset)\n        };\n        Vector3 farthest = corners[0];\n        float best = -1f;\n        foreach (Vector3 corner in corners)\n        {\n            float distance = (new Vector2(corner.x - from.x, corner.z - from.z)).sqrMagnitude;\n            if (distance > best) { best = distance; farthest = corner; }\n        }\n        return ClampToTerrain(farthest);\n    }\n\n    void BuildExitBeacon(Vector3 position)\n    {\n        if (escapeBeacon != null) Destroy(escapeBeacon.gameObject);\n        GameObject beacon = new GameObject(\"Red Exit Beacon — End of Map\");\n        escapeBeacon = beacon.transform;\n        escapeBeacon.position = position;\n        Color red = new Color(.9f, .045f, .025f);\n        CulturePrimitive(escapeBeacon, PrimitiveType.Cube, \"Exit arch left\", position + Vector3.up * 3f + Vector3.left * 3f, new Vector3(.7f, 6f, .7f), new Color(.12f, .12f, .1f));\n        CulturePrimitive(escapeBeacon, PrimitiveType.Cube, \"Exit arch right\", position + Vector3.up * 3f + Vector3.right * 3f, new Vector3(.7f, 6f, .7f), new Color(.12f, .12f, .1f));\n        CulturePrimitive(escapeBeacon, PrimitiveType.Cube, \"Exit arch lintel\", position + Vector3.up * 6f, new Vector3(6.7f, .7f, .7f), new Color(.12f, .12f, .1f));\n        CulturePrimitive(escapeBeacon, PrimitiveType.Cylinder, \"Vertical red light\", position + Vector3.up * 12f, new Vector3(.3f, 12f, .3f), red, true);\n        AddCultureLight(escapeBeacon, position + Vector3.up * 8f, red, 5f, 40f);\n    }\n\n    void CreateGod(Vector3 spawn)\n    {\n        if (godRoot != null) Destroy(godRoot.gameObject);\n        GameObject god = new GameObject(\"The God — Colossal Bipedal Coyote\");\n        godRoot = god.transform;\n        godRoot.position = ClampToTerrain(spawn);\n        godRoot.rotation = Quaternion.LookRotation(player.position - godRoot.position);\n        float desiredHeight = GetPlayerWorldHeight() * currentGodHeightInPlayerHeights;\n        float modelHeight = 2.4f;\n        godRoot.localScale = Vector3.one * (desiredHeight / modelHeight);\n        Color fur = new Color(.095f, .065f, .055f);\n        Color muzzle = new Color(.18f, .11f, .09f);\n        Color eye = new Color(.95f, .035f, .015f);\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Cube, \"Massive torso\", new Vector3(0f, 1.35f, 0f), new Vector3(1.25f, 1.25f, .72f), fur);\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Sphere, \"Coyote head\", new Vector3(0f, 2.05f, .12f), new Vector3(.82f, .75f, .7f), fur);\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Cube, \"Long muzzle\", new Vector3(0f, 1.95f, .55f), new Vector3(.48f, .28f, .72f), muzzle);\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Cube, \"Coyote ear left\", new Vector3(-.28f, 2.52f, -.03f), new Vector3(.22f, .55f, .2f), fur, Quaternion.Euler(0f, 0f, -8f));\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Cube, \"Coyote ear right\", new Vector3(.28f, 2.52f, -.03f), new Vector3(.22f, .55f, .2f), fur, Quaternion.Euler(0f, 0f, 8f));\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Sphere, \"Left burning eye\", new Vector3(-.19f, 2.12f, .45f), new Vector3(.12f, .1f, .08f), eye, null, true);\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Sphere, \"Right burning eye\", new Vector3(.19f, 2.12f, .45f), new Vector3(.12f, .1f, .08f), eye, null, true);\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Cube, \"Left long leg\", new Vector3(-.42f, .36f, -.05f), new Vector3(.38f, .75f, .4f), fur);\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Cube, \"Right long leg\", new Vector3(.42f, .36f, -.05f), new Vector3(.38f, .75f, .4f), fur);\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Cube, \"Left long arm\", new Vector3(-.92f, 1.33f, .05f), new Vector3(.35f, 1.15f, .38f), fur, Quaternion.Euler(0f, 0f, 14f));\n        GameObject hand = CampaignPrimitiveLocal(godRoot, PrimitiveType.Sphere, \"Grabbing hand\", new Vector3(-1.03f, .72f, .12f), new Vector3(.52f, .38f, .48f), fur);\n        godHand = hand.transform;\n        CampaignPrimitiveLocal(godRoot, PrimitiveType.Cube, \"Right long arm\", new Vector3(.92f, 1.33f, .05f), new Vector3(.35f, 1.15f, .38f), fur, Quaternion.Euler(0f, 0f, -14f));\n        godHead = godRoot;\n        CapsuleCollider bossCollider = godRoot.gameObject.AddComponent<CapsuleCollider>();\n        bossCollider.center = new Vector3(0f, 1.2f, 0f);\n        bossCollider.height = modelHeight;\n        bossCollider.radius = .75f;\n        bossCollider.enabled = false;\n    }\n\n    void PlayGodChant()\n    {\n        if (godChantSource == null)\n        {\n            godChantSource = gameObject.AddComponent<AudioSource>();\n            godChantSource.spatialBlend = 0f;\n            godChantSource.loop = true;\n            godChantSource.playOnAwake = false;\n            godChantSource.ignoreListenerVolume = true;\n        }\n        campaignChant = chantAudio;\n        godChantSource.clip = campaignChant;\n        godChantSource.volume = godChantVolume;\n        if (campaignChant != null) godChantSource.Play();\n    }\n\n    void UpdateCampaignRuntime()\n    {\n        if (phase == Phase.Level3) UpdateMapMarkers();\n        if (phase == Phase.Level4) UpdateGodChase();\n    }\n\n    void UpdateGodChase()\n    {\n        if (godRoot == null || godSequenceRunning) return;\n        float elapsed = Mathf.Max(0f, Time.time - godChaseStartTime);\n        currentGodHeightInPlayerHeights = Mathf.Min(\n            Mathf.Max(godHeightInPlayerHeights, godMaxHeightInPlayerHeights),\n            godHeightInPlayerHeights + elapsed * Mathf.Max(0f, godGrowthPlayerHeightsPerSecond));\n        godRoot.localScale = Vector3.one * (GetPlayerWorldHeight() * currentGodHeightInPlayerHeights / 2.4f);\n        Vector3 target = player.position;\n        target.y = godRoot.position.y;\n        Vector3 next = Vector3.MoveTowards(godRoot.position, target, godChaseSpeed * Time.deltaTime);\n        next.y = terrain != null ? terrain.SampleHeight(next) + terrain.transform.position.y : godRoot.position.y;\n        godRoot.position = next;\n        Vector3 look = player.position - godRoot.position;\n        look.y = 0f;\n        if (look.sqrMagnitude > .01f) godRoot.rotation = Quaternion.LookRotation(look);\n        if (godOmenText != null)\n        {\n            if (Time.time >= nextGodOmenTime)\n            {\n                StartCoroutine(PulseGodOmen());\n                nextGodOmenTime = Time.time + 7.5f;\n            }\n        }\n        bool catchGraceFinished = elapsed >= Mathf.Max(0f, godCatchGraceSeconds);\n        if (Time.time >= nextGraceHudUpdate && elapsed < godCatchGraceSeconds)\n        {\n            UpdateHud();\n            nextGraceHudUpdate = Time.time + 1f;\n        }\n        if (Vector3.Distance(player.position, godExitPosition) <= godExitInset)\n            StartCoroutine(GodEdgeEndingSequence());\n        else if (catchGraceFinished && Vector3.Distance(godRoot.position, player.position) <= godGrabDistance)\n            StartCoroutine(GodCaptureSequence());\n    }\n\n    IEnumerator GodEdgeEndingSequence()\n    {\n        if (godEdgeSequenceRunning || godSequenceRunning) yield break;\n        godEdgeSequenceRunning = true;\n        phase = Phase.CampaignTransition;\n        IsPlaying = false;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        if (movement != null) movement.enabled = false;\n        if (godRoot != null)\n        {\n            godRoot.position = ClampToTerrain(player.position - player.forward * 10f);\n            Vector3 toPlayer = player.position - godRoot.position;\n            toPlayer.y = 0f;\n            if (toPlayer.sqrMagnitude > .01f) godRoot.rotation = Quaternion.LookRotation(toPlayer);\n            if (playerCamera != null)\n                playerCamera.rotation = Quaternion.LookRotation(godRoot.position + Vector3.up * (GetPlayerWorldHeight() * currentGodHeightInPlayerHeights * .72f) - playerCamera.position);\n        }\n        dialoguePanel.SetActive(true);\n        string[] lines =\n        {\n            \"Futile. There is no running away from God.\",\n            \"This is my dimension.\",\n            \"No matter what, I am going to eat you.\"\n        };\n        foreach (string line in lines)\n        {\n            dialogueText.text = line;\n            yield return new WaitForSeconds(3f);\n        }\n        dialoguePanel.SetActive(false);\n        if (movement != null) movement.enabled = true;\n        godEdgeSequenceRunning = false;\n        phase = Phase.Level4;\n        IsPlaying = true;\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        StartCoroutine(GodCaptureSequence());\n    }\n\n    float GetPlayerWorldHeight()\n    {\n        CharacterController controller = player != null ? player.GetComponent<CharacterController>() : null;\n        return controller != null ? controller.height * player.lossyScale.y : 2f * (player != null ? player.lossyScale.y : 1f);\n    }\n\n    IEnumerator PulseGodOmen()\n    {\n        if (godOmenText == null || phase != Phase.Level4) yield break;\n        godOmenText.gameObject.SetActive(true);\n        float duration = 2.5f;\n        for (float t = 0f; t < duration; t += Time.deltaTime)\n        {\n            float fade = Mathf.Sin((t / duration) * Mathf.PI);\n            godOmenText.color = new Color(1f, .035f, .02f, fade * .9f);\n            yield return null;\n        }\n        if (phase == Phase.Level4) godOmenText.color = new Color(1f, .035f, .02f, 0f);\n    }\n\n    IEnumerator GodCaptureSequence()\n    {\n        if (godSequenceRunning) yield break;\n        godSequenceRunning = true;\n        phase = Phase.FinalEnding;\n        IsPlaying = false;\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        if (godChantSource != null) godChantSource.volume = Mathf.Min(1f, godChantVolume * 1.5f);\n        hintText.text = \"\";\n        dialoguePanel.SetActive(false);\n        if (campaignMapPanel != null) campaignMapPanel.SetActive(false);\n        if (movement != null) movement.enabled = false;\n        Vector3 start = player.position;\n        float godHeight = Mathf.Max(godHeightInPlayerHeights, currentGodHeightInPlayerHeights);\n        Vector3 mouth = godRoot != null ? godRoot.position + godRoot.up * (godHeight * 1.15f) + godRoot.forward * (godHeight * .2f) : start + Vector3.up * 3f;\n        if (godHand != null)\n        {\n            Vector3 startHand = godHand.localPosition;\n            Vector3 endHand = new Vector3(startHand.x, 1.45f, .8f);\n            float handElapsed = 0f;\n            while (handElapsed < 1.5f)\n            {\n                godHand.localPosition = Vector3.Lerp(startHand, endHand, handElapsed / 1.5f);\n                handElapsed += Time.deltaTime;\n                yield return null;\n            }\n        }\n        float liftDuration = 3.4f;\n        float liftElapsed = 0f;\n        Vector3 capturePoint = godRoot != null ? mouth + godRoot.forward * (godHeight * .05f) : mouth;\n        while (liftElapsed < liftDuration)\n        {\n            float t = liftElapsed / liftDuration;\n            player.position = Vector3.Lerp(start, capturePoint, t);\n            if (playerCamera != null && godRoot != null)\n            {\n                Vector3 gaze = godRoot.position + Vector3.up * (godHeight * .78f);\n                playerCamera.rotation = Quaternion.Slerp(playerCamera.rotation, Quaternion.LookRotation(gaze - playerCamera.position), Time.deltaTime * 2f);\n            }\n            liftElapsed += Time.deltaTime;\n            yield return null;\n        }\n        AudioClip deathClip = playerDeathSound != null ? playerDeathSound : coyoteJumpscareSound;\n        if (deathClip != null && audioSource != null) audioSource.PlayOneShot(deathClip, playerDeathSoundVolume);\n        if (blackoutOverlay != null) blackoutOverlay.gameObject.SetActive(true);\n        if (blackoutOverlay != null) blackoutOverlay.color = new Color(0f, 0f, 0f, 0f);\n        for (float t = 0f; t < godFinalFadeSeconds; t += Time.deltaTime)\n        {\n            float alpha = Mathf.Clamp01(t / godFinalFadeSeconds);\n            if (blackoutOverlay != null) blackoutOverlay.color = new Color(.02f, 0f, 0f, alpha);\n            yield return null;\n        }\n        if (godChantSource != null) godChantSource.Stop();\n        if (godOmenText != null) godOmenText.gameObject.SetActive(false);\n        if (blackoutOverlay != null) blackoutOverlay.gameObject.SetActive(false);\n        ShowFinalEnding();\n    }\n\n    void ShowFinalEnding()\n    {\n        phase = Phase.Complete;\n        IsPlaying = false;\n        if (endPanel != null) Destroy(endPanel);\n        endPanel = NewPanel(canvas.transform, \"The End\", Vector2.zero, Vector2.one, new Color(.008f, .006f, .008f, .96f));\n        Text title = NewText(endPanel.transform, \"The End Title\", \"THE END\\nThank you for playing\", 46, new Vector2(.12f, .47f), new Vector2(.88f, .69f));\n        title.alignment = TextAnchor.MiddleCenter;\n        CreateEndButton(endPanel.transform, \"RESTART LEVEL 1\", () => RestartLevelOne(false));\n    }\n\n    void ToggleCampaignMap()\n    {\n        if (phase != Phase.Level3 || campaignMapPanel == null) return;\n        mapOpen = !mapOpen;\n        campaignMapPanel.SetActive(mapOpen);\n        if (mapOpen)\n        {\n            movementWasEnabledBeforeMap = movement != null && movement.enabled;\n            if (movement != null) movement.enabled = false;\n            UpdateMapMarkers();\n            hintText.text = \"Amber dots are unread notes. Explore the Camp, Temple, Eyes, and Shelter landmarks.\";\n        }\n        else\n        {\n            if (movement != null) movement.enabled = movementWasEnabledBeforeMap;\n            hintText.text = \"The nearest unread note is marked on your map. Keep exploring before time runs out.\";\n        }\n    }\n\n    void UpdateMapMarkers()\n    {\n        if (campaignMapArea == null || terrain == null || terrain.terrainData == null) return;\n        Vector2 playerCoord = TerrainMapCoordinate(player.position);\n        SetMapDot(campaignPlayerDot, playerCoord, true);\n        Vector3[] sitePositions = { cultureCampPosition, cultureTemplePosition, cultureEyeGrovePosition, cultureShelterPosition };\n        string[] siteNames = { \"CAMP\", \"TEMPLE\", \"EYES\", \"SHELTER\" };\n        for (int i = 0; i < cultureMapDots.Count && i < sitePositions.Length; i++)\n        {\n            Vector2 site = TerrainMapCoordinate(sitePositions[i]);\n            SetMapDot(cultureMapDots[i], site, true);\n            RectTransform labelRect = cultureMapLabels[i].rectTransform;\n            labelRect.anchorMin = site;\n            labelRect.anchorMax = site;\n            labelRect.pivot = new Vector2(0f, .5f);\n            labelRect.anchoredPosition = new Vector2(9f, 9f);\n            cultureMapLabels[i].text = siteNames[i];\n        }\n        if (campaignNotePositions == null) return;\n        for (int i = 0; i < campaignNoteMapDots.Count; i++)\n        {\n            bool available = i < campaignNotePositions.Length && !foundCampaignNoteIndices.Contains(i);\n            Vector2 noteCoord = available ? TerrainMapCoordinate(campaignNotePositions[i]) : Vector2.zero;\n            SetMapDot(campaignNoteMapDots[i], noteCoord, available);\n        }\n    }\n\n    Vector2 TerrainMapCoordinate(Vector3 world)\n    {\n        Vector3 origin = terrain.transform.position;\n        Vector3 size = terrain.terrainData.size;\n        return new Vector2(Mathf.Clamp01((world.x - origin.x) / size.x), Mathf.Clamp01((world.z - origin.z) / size.z));\n    }\n\n    void SetMapDot(Image dot, Vector2 normalized, bool visible)\n    {\n        if (dot == null) return;\n        dot.gameObject.SetActive(visible);\n        RectTransform rect = dot.rectTransform;\n        rect.anchorMin = normalized;\n        rect.anchorMax = normalized;\n        rect.anchoredPosition = Vector2.zero;\n    }\n\n    void ResetCampaignProgress()\n    {\n        gunUnlocked = false;\n        coyotesKilled = 0;\n        levelThreeNotesFound = 0;\n        foundCampaignNoteIndices.Clear();\n        levelThreeDeadlineRemaining = 0f;\n        advanceToLevelFour = false;\n        mapOpen = false;\n        godSequenceRunning = false;\n        if (campaignMapPanel != null) campaignMapPanel.SetActive(false);\n        if (godOmenText != null) godOmenText.gameObject.SetActive(false);\n        if (campaignCrosshair != null) campaignCrosshair.gameObject.SetActive(false);\n        if (gunModel != null) Destroy(gunModel);\n        gunModel = null;\n        if (godRoot != null) Destroy(godRoot.gameObject);\n        godRoot = null;\n        if (escapeBeacon != null) Destroy(escapeBeacon.gameObject);\n        escapeBeacon = null;\n        if (godChantSource != null) godChantSource.Stop();\n        RestoreCultureLighting();\n    }\n\n    void RestoreCultureLighting()\n    {\n        RenderSettings.fog = originalFog;\n        RenderSettings.fogMode = originalFogMode;\n        RenderSettings.fogDensity = originalFogDensity;\n        RenderSettings.fogColor = originalFogColor;\n        RenderSettings.ambientLight = originalAmbientColor;\n        RenderSettings.ambientIntensity = originalAmbientIntensity;\n        RenderSettings.reflectionIntensity = originalReflectionIntensity;\n        if (directionalLight != null) directionalLight.intensity = originalDirectionalIntensity;\n        if (gameplayCamera != null) gameplayCamera.farClipPlane = originalCameraFarClip;\n    }\n\n    string FormatCampaignTime(float seconds)\n    {\n        int totalSeconds = Mathf.Max(0, Mathf.CeilToInt(seconds));\n        return (totalSeconds / 60).ToString(\"00\") + \":\" + (totalSeconds % 60).ToString(\"00\");\n    }\n\n    void RestartCampaignCheckpoint()\n    {\n        if (endPanel != null) Destroy(endPanel);\n        if (phaseBeforeGameOver == Phase.Level4)\n        {\n            RestartLevelFour();\n            return;\n        }\n        if (phaseBeforeGameOver == Phase.Level2IntroCoyote)\n        {\n            StartCoroutine(LevelTwoIntroSequence());\n            return;\n        }\n        if (phaseBeforeGameOver == Phase.Level2)\n        {\n            StartCoroutine(RestartLevelTwoRoutine());\n            return;\n        }\n        if (phaseBeforeGameOver == Phase.Level3)\n        {\n            RestartLevelThree();\n            return;\n        }\n        RestartLevelOne(true);\n    }\n\n    void RestartLevelFour()\n    {\n        if (endPanel != null) Destroy(endPanel);\n        ClearGameplayObjects();\n        if (godRoot != null) Destroy(godRoot.gameObject);\n        if (escapeBeacon != null) Destroy(escapeBeacon.gameObject);\n        godRoot = null;\n        godHand = null;\n        godHead = null;\n        escapeBeacon = null;\n        if (godChantSource != null) godChantSource.Stop();\n        player.position = levelFourStartPosition;\n        player.rotation = levelFourStartRotation;\n        if (playerCamera != null)\n        {\n            playerCamera.SetParent(player, false);\n            playerCamera.localPosition = new Vector3(0f, 1.5f, 0f);\n            playerCamera.localRotation = Quaternion.identity;\n            cameraBaseLocalPosition = playerCamera.localPosition;\n        }\n        if (movement != null)\n        {\n            movement.enabled = true;\n            movement.ResetView();\n        }\n        godSequenceRunning = false;\n        godEdgeSequenceRunning = false;\n        BeginLevelFour();\n    }\n\n    IEnumerator RestartLevelTwoRoutine()\n    {\n        ClearGameplayObjects();\n        player.position = levelOneCheckpoint;\n        player.rotation = levelOneCheckpointRotation;\n        if (playerCamera != null)\n        {\n            playerCamera.SetParent(player, false);\n            playerCamera.localPosition = new Vector3(0f, 1.5f, 0f);\n            cameraBaseLocalPosition = playerCamera.localPosition;\n            playerCamera.localRotation = Quaternion.identity;\n        }\n        if (movement != null) movement.ResetView();\n        if (flashlight != null) flashlight.enabled = false;\n        hypothermia = startingHypothermia;\n        coldWarningShown = false;\n        CreateOrShowGun();\n        SetGunVisible(gunUnlocked);\n        levelCoyoteTimer = GetNextCoyoteSpawnDelay();\n        phase = Phase.Level2;\n        campaignMatchSpawnTimer = GetCampaignMatchSpawnDelay(phase);\n        IsPlaying = true;\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        dialoguePanel.SetActive(false);\n        ApplyLevelOneDarkness();\n        hintText.text = \"Press T to fire. A body hit kills; a miss scares the Coyote away.\";\n        UpdateHud();\n        yield return null;\n    }\n\n    void RestartLevelThree()\n    {\n        ClearGameplayObjects();\n        player.position = levelOneCheckpoint;\n        player.rotation = levelOneCheckpointRotation;\n        if (playerCamera != null)\n        {\n            playerCamera.SetParent(player, false);\n            playerCamera.localPosition = new Vector3(0f, 1.5f, 0f);\n            cameraBaseLocalPosition = playerCamera.localPosition;\n            playerCamera.localRotation = Quaternion.identity;\n        }\n        if (movement != null) movement.ResetView();\n        hypothermia = startingHypothermia;\n        coldWarningShown = false;\n        levelThreeNotesFound = foundCampaignNoteIndices.Count;\n        levelThreeDeadlineRemaining = levelThreeDeadlineSeconds;\n        levelCoyoteTimer = GetNextCoyoteSpawnDelay();\n        phase = Phase.Level3;\n        campaignMatchSpawnTimer = GetCampaignMatchSpawnDelay(phase);\n        IsPlaying = true;\n        Cursor.lockState = CursorLockMode.Locked;\n        Cursor.visible = false;\n        SpawnLevelThreeNotes();\n        StartCoroutine(LevelThreeDeadlineRoutine());\n        ApplyLevelOneDarkness();\n        UpdateHud();\n    }\n}\n"},"Movement":{"path":"Assets/Script/Movement.cs","role":"Provides tuned first-person walking, sprinting, jumping, and camera look.","source":"\nusing UnityEngine;\n\n// @role Provides tuned first-person walking, sprinting, jumping, and camera look.\n// @calls ForestGameManager\n// @tune moveSpeed:float:0-20:Base walking speed for exploration.\n// @tune jumpHeight:float:0-5:Player jump height.\n// @tune sprintMultiplier:float:1-3:Speed multiplier while holding Shift.\npublic class Movement : MonoBehaviour\n{\n    [Header(\"Camera\")]\n    [SerializeField] Transform playerCamera;\n    [SerializeField] float mouseSmoothTime = 0.03f;\n    [SerializeField] float mouseSensitivity = 3.5f;\n\n    [Header(\"Movement Tuning\")]\n    [Min(0f)] [SerializeField] private float moveSpeed = 4f;\n    [Tooltip(\"Hold Left Shift or Right Shift to run. The final escape is balanced around this value.\")]\n    [Min(1f)] [SerializeField] private float sprintMultiplier = 1.6f;\n    [Min(0f)] [SerializeField] private float jumpHeight = 0.75f;\n    [SerializeField] private float gravity = -25f;\n    [Min(0f)] [SerializeField] private float moveSmoothTime = 0.15f;\n\n    private float velocityY;\n    private bool wasPlaying;\n\n    private float cameraCap;\n    private Vector2 currentMouseDelta;\n    private Vector2 currentMouseDeltaVelocity;\n    private Vector2 currentDir;\n    private Vector2 currentDirVelocity;\n\n    private CharacterController controller;\n    private float defaultMoveSpeed;\n\n    public void SetMoveSpeed(float speed)\n    {\n        moveSpeed = Mathf.Max(0f, speed);\n    }\n\n    public void RestoreDefaultMoveSpeed()\n    {\n        moveSpeed = defaultMoveSpeed;\n    }\n\n    void Start()\n    {\n        defaultMoveSpeed = moveSpeed;\n        controller = GetComponent<CharacterController>();\n\n        if (controller == null)\n        {\n            Debug.LogError(\n                \"Movement requires a CharacterController!\"\n            );\n            enabled = false;\n            return;\n        }\n\n        // ForestGameManager controls the cursor so menus can keep it visible.\n    }\n\n    void Update()\n    {\n        if (!ForestGameManager.IsPlaying)\n        {\n            wasPlaying = false;\n            return;\n        }\n\n        if (!wasPlaying)\n        {\n            wasPlaying = true;\n            currentMouseDelta = Vector2.zero;\n            currentMouseDeltaVelocity = Vector2.zero;\n            currentDir = Vector2.zero;\n            currentDirVelocity = Vector2.zero;\n            return;\n        }\n\n        UpdateMouse();\n        UpdateMove();\n    }\n\n    void UpdateMouse()\n    {\n        if (playerCamera == null)\n            return;\n\n        Vector2 targetMouseDelta = new Vector2(\n            Input.GetAxis(\"Mouse X\"),\n            Input.GetAxis(\"Mouse Y\")\n        );\n\n        currentMouseDelta = Vector2.SmoothDamp(\n            currentMouseDelta,\n            targetMouseDelta,\n            ref currentMouseDeltaVelocity,\n            mouseSmoothTime\n        );\n\n        cameraCap -= currentMouseDelta.y * mouseSensitivity;\n        cameraCap = Mathf.Clamp(cameraCap, -90f, 90f);\n\n        playerCamera.localEulerAngles =\n            Vector3.right * cameraCap;\n\n        transform.Rotate(\n            Vector3.up *\n            currentMouseDelta.x *\n            mouseSensitivity\n        );\n    }\n\n    void UpdateMove()\n    {\n        bool isGrounded = controller.isGrounded;\n\n        // Keep the player on the ground.\n        if (isGrounded && velocityY < 0f)\n        {\n            velocityY = -2f;\n        }\n        else\n        {\n            // Accelerate downward while airborne.\n            velocityY += gravity * Time.deltaTime;\n        }\n\n        // Jump only when grounded.\n        if (isGrounded && Input.GetButtonDown(\"Jump\"))\n        {\n            velocityY = Mathf.Sqrt(\n                jumpHeight * -2f * gravity\n            );\n        }\n\n        Vector2 targetDir = new Vector2(\n            Input.GetAxisRaw(\"Horizontal\"),\n            Input.GetAxisRaw(\"Vertical\")\n        );\n\n        targetDir = Vector2.ClampMagnitude(targetDir, 1f);\n\n        currentDir = Vector2.SmoothDamp(\n            currentDir,\n            targetDir,\n            ref currentDirVelocity,\n            moveSmoothTime\n        );\n\n        bool sprinting = Input.GetKey(KeyCode.LeftShift) || Input.GetKey(KeyCode.RightShift);\n        float currentMoveSpeed = moveSpeed * (sprinting ? sprintMultiplier : 1f);\n        Vector3 horizontalVelocity =\n            (transform.forward * currentDir.y +\n             transform.right * currentDir.x) * currentMoveSpeed;\n\n        Vector3 moveVelocity =\n            horizontalVelocity + Vector3.up * velocityY;\n\n        controller.Move(moveVelocity * Time.deltaTime);\n    }\n\n    public void ResetView()\n    {\n        cameraCap = 0f;\n        currentMouseDelta = Vector2.zero;\n        currentMouseDeltaVelocity = Vector2.zero;\n        if (playerCamera != null) playerCamera.localEulerAngles = Vector3.zero;\n    }\n}\n"}}};
